const app = express();
const resend = new Resend(process.env.RESEND_API_KEY);
async function sendOrganizationNotification({
  to,
  subject,
  html,
  senderName = "Vivid",
  replyTo = "mike@vividspots.com"
}) {
  try {
    const cleanSenderName =
      String(senderName || "Vivid")
        .replace(/[\r\n<>"]/g, "")
        .trim() || "Vivid";

    const { data, error } = await resend.emails.send({
      from:
        `${cleanSenderName} <notifications@vividspots.com>`,

      to,

      replyTo,

      subject,

      html
    });

    if (error) {
      console.error(
        "ORGANIZATION NOTIFICATION ERROR:",
        error
      );

      return false;
    }

    console.log(
      "ORGANIZATION NOTIFICATION SENT:",
      data
    );

    return true;

  } catch (err) {
    console.error(
      "ORGANIZATION NOTIFICATION EXCEPTION:",
      err
    );

    return false;
  }
}
