function normalizeOrganizationRole(role) {
  const normalizedRole = String(role || "")
    .trim()
    .toLowerCase();

  if (
    normalizedRole === "owner" ||
    normalizedRole === "district_admin" ||
    normalizedRole === "organization_admin"
  ) {
    return "organization_admin";
  }

  if (normalizedRole === "location_manager") {
    return "location_manager";
  }

  return "read_only";
}
function getOrganizationRolePermissions(role) {
  const normalizedRole = String(
    role || "read_only"
  ).trim().toLowerCase();

  return (
    ORGANIZATION_ROLE_PERMISSIONS[normalizedRole] ||
    ORGANIZATION_ROLE_PERMISSIONS.read_only
  );
}

function organizationRoleHasPermission(role, permissionKey) {

  role = normalizeOrganizationRole(role);

  if (role === "organization_admin") {
    return true;
  }

  if (role === "location_manager") {

    const allowed = [
      "view_dashboard",
      "manage_advertisers",
      "manage_opportunities",
      "manage_requests",
      "approve_requests",
      "view_analytics",
      "export_reports"
    ];

    return allowed.includes(permissionKey);
  }

  const readOnly = [
    "view_dashboard",
    "view_analytics"
  ];

  return readOnly.includes(permissionKey);
}
function requireOrganizationPermission(permissionKey) {
  return (req, res, next) => {

    if (
      req.session.user?.role === "super_admin"
    ) {
      return next();
    }

    if (!req.session.orgUser) {
      return res.redirect("/org-login");
    }

    const role =
      req.session.orgUser.organization_role;

    if (
      !organizationRoleHasPermission(
        role,
        permissionKey
      )
    ) {
      return res
        .status(403)
        .send("Access denied");
    }

    next();
  };
}
/*
=========================================================
ORGANIZATION LOCATION ACCESS SCOPE
=========================================================

Organization Administrators:
- Can access every active location in their organization.

Location Managers and Read Only users:
- Can access only active locations assigned through location_users.

Super Admin access is handled by the calling route.
=========================================================
*/

async function getOrganizationLocationScope({
  organizationId,
  organizationUserId,
  organizationRole,
  db = q
}) {
  const normalizedRole =
    normalizeOrganizationRole(organizationRole);

  /*
    Organization Administrators have organization-wide access.
    null means the route should not add a location restriction.
  */
  if (normalizedRole === "organization_admin") {
    return {
      restricted: false,
      locationIds: []
    };
  }

  if (
    !Number.isInteger(organizationUserId) ||
    organizationUserId <= 0
  ) {
    return {
      restricted: true,
      locationIds: []
    };
  }

  const assignedLocationsResult = await db(
    `
      SELECT DISTINCT
        s.id
      FROM location_users lu

      JOIN spaces s
        ON s.id = lu.space_id
       AND s.organization_id = lu.organization_id

      WHERE lu.organization_id = $1
        AND lu.user_id = $2
        AND COALESCE(lu.is_active, true) = true
        AND COALESCE(s.is_archived, false) = false

      ORDER BY s.id
    `,
    [
      organizationId,
      organizationUserId
    ]
  );

  return {
    restricted: true,
    locationIds:
      assignedLocationsResult.rows.map(
        row => Number(row.id)
      )
  };
}
function requireAdmin(req, res, next) {

  if (!req.session.user) {
    return res.redirect("/login");
  }

  if (req.session.user.role !== "admin") {
    return res.send("Access denied");
  }

  next();
}
