app.get("/r/:qrId", async (req, res) => {
  try {
    const qrId = Number(req.params.qrId);

    if (
      !Number.isInteger(qrId) ||
      qrId <= 0
    ) {
      return res.status(400).send(
        "Valid QR ID required."
      );
    }

    const vividClickId =
      crypto.randomUUID();

    const safe = value =>
      String(value ?? "")
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#039;");

    /*
    =========================================================
    IMPORTED QR ROUTING

    Imported QR codes keep their existing direct destination.
    This working behavior remains unchanged.
    =========================================================
    */

    const importedQr = await q(
      `
        SELECT *
        FROM qr_codes
        WHERE id = $1
          AND is_imported = true
          AND description IS NOT NULL
          AND description LIKE 'http%'
        LIMIT 1
      `,
      [qrId]
    );

    if (importedQr.rows[0]) {
      const campaign =
        await activeCampaignForQr(qrId);

      const importedCampaignId =
        campaign?.campaign_id ||
        campaign?.id ||
        null;

      await saveEvent({
        qrId,
        campaignId: importedCampaignId,
        type: "scan",
        vividClickId
      });

      return res.redirect(
        addVividClickIdToUrl(
          importedQr.rows[0].description,
          vividClickId
        )
      );
    }

    /*
    =========================================================
    ACTIVE CAMPAIGN

    Existing campaign selection logic remains the source
    of truth for the QR.
    =========================================================
    */

    const campaign =
      await activeCampaignForQr(qrId);

    if (!campaign) {
      return res.status(404).send(
        "No active campaign assigned to this QR."
      );
    }

    const campaignId =
      campaign.campaign_id ||
      campaign.id;

    await saveEvent({
      qrId,
      campaignId,
      type: "scan",
      vividClickId
    });

    /*
    =========================================================
    CUSTOMER ACTION ROUTING

    One active Customer Action:
    - redirect through the tracked destination route

    Multiple active Customer Actions:
    - show the customer a simple selection page

    No Customer Actions:
    - continue to the existing store and legacy routing
    =========================================================
    */

    const customerActionsResult =
      await q(
        `
          SELECT
            id,
            name,
            destination_type,
            destination_url,
            display_order

          FROM campaign_destinations

          WHERE campaign_id = $1
            AND COALESCE(
                  is_active,
                  true
                ) = true

          ORDER BY
            display_order ASC,
            id ASC
        `,
        [campaignId]
      );

    const customerActions =
      customerActionsResult.rows;

    /*
      One active Customer Action:
      do not make the customer choose unnecessarily.
    */
    if (customerActions.length === 1) {
      const action =
        customerActions[0];

      return res.redirect(
        `/destination-click/${action.id}` +
        `?qr_id=${qrId}` +
        `&vivid_click_id=${encodeURIComponent(
          vividClickId
        )}`
      );
    }

    /*
      Multiple active Customer Actions:
      display the choices configured by the advertiser.
    */
    if (customerActions.length > 1) {
      const actionButtons =
        customerActions
          .map(
            action => `
              <a
                class="choice-btn"
                href="/destination-click/${action.id}?qr_id=${qrId}&vivid_click_id=${encodeURIComponent(
                  vividClickId
                )}"
              >
                ${safe(
                  action.name ||
                  "Open"
                )}
              </a>
            `
          )
          .join("");

      return res.send(
        page(
          "Vivid Customer Experience",
          `
            <div class="topbar">
              <div class="brand">
                Vivid Spots
              </div>

              <h1>
                ${safe(
                  campaign.advertiser ||
                  "Campaign"
                )}
              </h1>

              <p class="subtitle">
                ${safe(
                  campaign.name || ""
                )}
              </p>
            </div>

            <div class="wrap">
              <div class="choice-card">

                ${
                  campaign.is_deal_of_day
                    ? `
                        <span class="deal">
                          🔥 Deal of the Day
                        </span>
                      `
                    : `
                        <span class="pill">
                          Customer Actions
                        </span>
                      `
                }

                <h1>
                  What would you like to do?
                </h1>

                <p>
                  Choose an option below.
                </p>

                ${actionButtons}

                <p class="small">
                  Powered by Vivid
                </p>

              </div>
            </div>
          `
        )
      );
    }

    /*
    =========================================================
    EXISTING STORE ROUTING FALLBACK

    This runs only when the campaign has no configured
    Customer Actions.
    =========================================================
    */

    try {
      const routedStore = await q(
        `
          SELECT
            s.*

          FROM campaign_stores cs

          JOIN stores s
            ON s.id = cs.store_id

          WHERE cs.campaign_id = $1
            AND s.maps_url IS NOT NULL
            AND s.maps_url <> ''

          ORDER BY
            CASE
              WHEN s.inventory_status = 'high'
                THEN 1
              WHEN s.inventory_status = 'normal'
                THEN 2
              WHEN s.inventory_status = 'low'
                THEN 3
              ELSE 4
            END,
            s.id ASC

          LIMIT 1
        `,
        [campaignId]
      );

      if (routedStore.rows[0]) {
        await saveEvent({
          qrId,
          campaignId,
          storeId:
            routedStore.rows[0].id ||
            null,
          type: "maps",
          vividClickId
        });

        return res.redirect(
          addVividClickIdToUrl(
            routedStore.rows[0].maps_url,
            vividClickId
          )
        );
      }
    } catch (err) {
      console.error(
        "STORE ROUTING ERROR:",
        err
      );

      return res.status(500).send(
        "STORE ROUTING ERROR: " +
        err.message
      );
    }

    /*
    =========================================================
    LEGACY CUSTOMER EXPERIENCE FALLBACK

    Existing campaigns without Customer Actions continue
    using Offer, Maps and Waze.
    =========================================================
    */

    return res.send(
      page(
        "Vivid QR Experience",
        `
          <div class="topbar">
            <div class="brand">
              Vivid Spots
            </div>

            <h1>
              ${safe(
                campaign.advertiser ||
                "Campaign"
              )}
            </h1>

            <p class="subtitle">
              ${safe(
                campaign.name || ""
              )}
            </p>
          </div>

          <div class="wrap">
            <div class="choice-card">

              ${
                campaign.is_deal_of_day
                  ? `
                      <span class="deal">
                        🔥 Deal of the Day
                      </span>
                    `
                  : `
                      <span class="pill">
                        Smart Campaign
                      </span>
                    `
              }

              <h1>
                ${safe(
                  campaign.name ||
                  "Campaign"
                )}
              </h1>

              <p>
                <b>QR:</b>
                ${safe(
                  campaign.qr_name ||
                  qrId
                )}

                <br>

                <b>Location:</b>
                ${safe(
                  campaign.space_name ||
                  ""
                )}
              </p>

              <a
                class="choice-btn"
                href="/click/offer/${qrId}?vivid_click_id=${encodeURIComponent(
                  vividClickId
                )}"
              >
                View Offer
              </a>

              <a
                class="choice-btn dark"
                href="/click/maps/${qrId}?vivid_click_id=${encodeURIComponent(
                  vividClickId
                )}"
              >
                Find Store on Google Maps
              </a>

              <a
                class="choice-btn dark"
                href="/click/waze/${qrId}?vivid_click_id=${encodeURIComponent(
                  vividClickId
                )}"
              >
                Open in Waze
              </a>

              <p class="small">
                Vivid routes traffic based on campaign,
                performance, schedule, and inventory priority.
              </p>

            </div>
          </div>
        `
      )
    );
  } catch (err) {
    console.error(
      "QR ROUTING ERROR:",
      err
    );

    return res.status(500).send(
      "Unable to load the Vivid experience: " +
      err.message
    );
  }
});

app.get("/conversion", async (req, res) => {
  try {
    const vividClickId = String(
      req.query.vivid_click_id ||
      req.query.click_id ||
      ""
    ).trim();

    const pageUrl = String(
      req.query.page_url || ""
    ).trim();

    const suppliedValue =
      req.query.value !== undefined
        ? Number(req.query.value || 0)
        : null;

    if (!vividClickId) {
      return res.status(400).send(
        "Missing vivid_click_id"
      );
    }

    if (!pageUrl) {
      return res.status(400).send(
        "Missing page URL"
      );
    }

    /*
    =========================================================
    FIND THE ORIGINAL QR SCAN

    This remains the source for:
    - QR
    - Campaign
    - Store
    - Journey / click ID
    =========================================================
    */

    const scanResult = await q(
      `
        SELECT *
        FROM events

        WHERE vivid_click_id = $1
          AND type = 'scan'

        ORDER BY
          created_at ASC,
          id ASC

        LIMIT 1
      `,
      [vividClickId]
    );

    const scan = scanResult.rows[0];

    if (!scan) {
      return res.status(400).send(
        "Invalid vivid_click_id"
      );
    }

    /*
    =========================================================
    LOAD CAMPAIGN FALLBACK VALUES

    Existing campaigns continue using:
    - campaigns.conversion_url
    - campaigns.avg_customer_value
    =========================================================
    */

    const campaignResult = await q(
      `
        SELECT
          id,
          conversion_url,
          avg_customer_value

        FROM campaigns

        WHERE id = $1

        LIMIT 1
      `,
      [scan.campaign_id]
    );

    const campaign =
      campaignResult.rows[0];

    if (!campaign) {
      return res.status(400).send(
        "Campaign not found"
      );
    }

    /*
    =========================================================
    FIND CUSTOMER ACTIONS CLICKED IN THIS JOURNEY

    More than one Customer Action may have been clicked
    after the same scan.

    Newest click is listed first.
    =========================================================
    */

    const destinationClicksResult = await q(
      `
        SELECT
          e.id AS click_event_id,
          e.campaign_destination_id,
          e.created_at AS clicked_at,

          cd.name,
          cd.destination_url,
          cd.conversion_url,
          cd.estimated_value

        FROM events e

        JOIN campaign_destinations cd
          ON cd.id =
             e.campaign_destination_id

        WHERE e.vivid_click_id = $1
          AND e.campaign_id = $2
          AND e.type = 'destination_click'

        ORDER BY
          e.created_at DESC,
          e.id DESC
      `,
      [
        vividClickId,
        scan.campaign_id
      ]
    );

    const destinationClicks =
      destinationClicksResult.rows;

    /*
    =========================================================
    SAFE URL MATCHING

    Conversion page must match:
    - hostname
    - pathname

    Query parameters do not prevent a match.
    Trailing slashes do not prevent a match.
    =========================================================
    */

    const urlsMatch = (
      configuredUrl,
      actualPageUrl
    ) => {
      if (
        !configuredUrl ||
        !actualPageUrl
      ) {
        return false;
      }

      try {
        const expected =
          new URL(configuredUrl);

        const actual =
          new URL(actualPageUrl);

        const expectedPath =
          expected.pathname.replace(
            /\/$/,
            ""
          );

        const actualPath =
          actual.pathname.replace(
            /\/$/,
            ""
          );

        return (
          expected.hostname
            .toLowerCase() ===
          actual.hostname
            .toLowerCase() &&
          expectedPath === actualPath
        );
      } catch (err) {
        return false;
      }
    };

    /*
    =========================================================
    RESOLVE THE CUSTOMER ACTION

    Priority 1:
    Exact Customer Action conversion URL match.

    Priority 2:
    Campaign conversion URL match, attributed to the most
    recently clicked Customer Action.

    Priority 3:
    Legacy campaign conversion with no Customer Action.
    =========================================================
    */

    let matchedDestination = null;

    for (
      const destination of
      destinationClicks
    ) {
      if (
        urlsMatch(
          destination.conversion_url,
          pageUrl
        )
      ) {
        matchedDestination =
          destination;

        break;
      }
    }

    const campaignUrlMatches =
      urlsMatch(
        campaign.conversion_url,
        pageUrl
      );

    if (
      !matchedDestination &&
      campaignUrlMatches &&
      destinationClicks.length
    ) {
      matchedDestination =
        destinationClicks[0];
    }

    const destinationUrlMatched =
      Boolean(matchedDestination);

    const legacyCampaignMatched =
      !destinationUrlMatched &&
      campaignUrlMatches;

    if (
      !destinationUrlMatched &&
      !legacyCampaignMatched
    ) {
      return res
        .status(200)
        .send("Not conversion page");
    }

    const campaignDestinationId =
      matchedDestination
        ? Number(
            matchedDestination
              .campaign_destination_id
          )
        : null;

    /*
    =========================================================
    PREVENT DUPLICATE CONVERSIONS

    Duplicate protection is now per:
    - journey
    - campaign
    - Customer Action

    This allows one journey to convert through more than
    one Customer Action while preventing the same conversion
    from being recorded repeatedly.
    =========================================================
    */

    const duplicateResult = await q(
      `
        SELECT id
        FROM events

        WHERE vivid_click_id = $1
          AND campaign_id = $2
          AND type = 'conversion'

          AND (
            (
              $3::int IS NULL
              AND campaign_destination_id
                  IS NULL
            )
            OR
            campaign_destination_id =
              $3::int
          )

        LIMIT 1
      `,
      [
        vividClickId,
        scan.campaign_id,
        campaignDestinationId
      ]
    );

    if (duplicateResult.rows.length) {
      return res
        .status(200)
        .send(
          "Conversion already tracked"
        );
    }

    /*
    =========================================================
    RESOLVE CONVERSION VALUE

    Priority:
    1. Explicit transaction value supplied by the site
    2. Customer Action estimated value
    3. Campaign default customer value
    =========================================================
    */

    let conversionValue = 0;

    if (
      suppliedValue !== null &&
      Number.isFinite(suppliedValue)
    ) {
      conversionValue =
        suppliedValue;
    } else if (
      matchedDestination &&
      Number(
        matchedDestination
          .estimated_value || 0
      ) > 0
    ) {
      conversionValue =
        Number(
          matchedDestination
            .estimated_value || 0
        );
    } else {
      conversionValue =
        Number(
          campaign.avg_customer_value ||
          0
        );
    }

    /*
    =========================================================
    SAVE THE ATTRIBUTED CONVERSION

    The conversion now carries:
    - QR
    - Campaign
    - Customer Action
    - Journey ID
    - Revenue value
    =========================================================
    */

    await saveEvent({
      qrId: scan.qr_id,
      campaignId:
        scan.campaign_id,
      storeId:
        scan.store_id,
      campaignDestinationId,
      vividSessionId:
        scan.vivid_session_id ||
        null,
      type: "conversion",
      value: conversionValue,
      vividClickId
    });

    /*
      Keep the original scan-level conversion timestamp
      for compatibility with existing Vivid logic.

      It is no longer used as the duplicate gate because
      one journey may convert through multiple actions.
    */

    await q(
      `
        UPDATE events

        SET converted_at =
          COALESCE(
            converted_at,
            CURRENT_TIMESTAMP
          )

        WHERE id = $1
      `,
      [scan.id]
    );

    return res
      .status(200)
      .send("Conversion tracked");
  } catch (err) {
    console.error(
      "CONVERSION TRACKING ERROR:",
      err
    );

    return res.status(500).send(
      "CONVERSION TRACKING ERROR: " +
      err.message
    );
  }
});

