/*
---------------------------------------------------------
DEACTIVATE
Preserves all historical data.
Removes Organization from Active list.
Disables Enterprise memberships.
---------------------------------------------------------
*/

app.post(
  "/org-organizations/:id/deactivate",
  requireLogin,
  requireSuperAdmin,
  async (req, res) => {
    try {

      const organizationId =
        Number(req.params.id);

      if (
        !Number.isInteger(organizationId) ||
        organizationId <= 0
      ) {
        return res
          .status(400)
          .send(
            "Valid organization required."
          );
      }


      await q(
        `
          UPDATE organizations

          SET
            is_active = false,
            updated_at = CURRENT_TIMESTAMP

          WHERE id = $1
        `,
        [organizationId]
      );


      await q(
        `
          UPDATE organization_users

          SET
            is_active = false

          WHERE organization_id = $1
        `,
        [organizationId]
      );


      return res.redirect(
        "/org-organizations?status=active"
      );


    } catch (err) {

      console.error(
        "DEACTIVATE ORGANIZATION ERROR:",
        err
      );

      return res
        .status(500)
        .send(
          "Unable to deactivate organization: " +
          err.message
        );
    }
  }
);


/*
---------------------------------------------------------
REACTIVATE
Restores Organization.

NOTE:
Memberships are intentionally NOT automatically restored.
We will manage individual user activation separately.
---------------------------------------------------------
*/

app.post(
  "/org-organizations/:id/reactivate",
  requireLogin,
  requireSuperAdmin,
  async (req, res) => {
    try {

      const organizationId =
        Number(req.params.id);

      if (
        !Number.isInteger(organizationId) ||
        organizationId <= 0
      ) {
        return res
          .status(400)
          .send(
            "Valid organization required."
          );
      }


      await q(
        `
          UPDATE organizations

          SET
            is_active = true,
            updated_at = CURRENT_TIMESTAMP

          WHERE id = $1
        `,
        [organizationId]
      );


      return res.redirect(
        "/org-organizations?status=active"
      );


    } catch (err) {

      console.error(
        "REACTIVATE ORGANIZATION ERROR:",
        err
      );

      return res
        .status(500)
        .send(
          "Unable to reactivate organization: " +
          err.message
        );
    }
  }
);


/*
---------------------------------------------------------
PERMANENT DELETE
TEST / JUNK ORGANIZATIONS ONLY.

Deletion is blocked if the Organization has business data.
---------------------------------------------------------
*/

app.post(
  "/org-organizations/:id/delete",
  requireLogin,
  requireSuperAdmin,
  async (req, res) => {
    try {

      const organizationId =
        Number(req.params.id);

      if (
        !Number.isInteger(organizationId) ||
        organizationId <= 0
      ) {
        return res
          .status(400)
          .send(
            "Valid organization required."
          );
      }


      const organizationResult =
        await q(
          `
            SELECT
              id,
              name,
              is_active

            FROM organizations

            WHERE id = $1

            LIMIT 1
          `,
          [organizationId]
        );


      const organization =
        organizationResult.rows[0];


      if (!organization) {
        return res
          .status(404)
          .send(
            "Organization not found."
          );
      }


      /*
      Only archived Organizations can be
      permanently deleted.
      */

      if (
        organization.is_active !== false
      ) {
        return res
          .status(400)
          .send(
            "Deactivate this organization before permanently deleting it."
          );
      }


      /*
      Check for business/history records.

      Any real Organization with business data
      must remain archived instead of deleted.
      */

      const usageResult =
        await q(
          `
            SELECT

              (
                SELECT COUNT(*)
                FROM spaces
                WHERE organization_id = $1
              )::int AS locations,

              (
                SELECT COUNT(*)
                FROM contracts
                WHERE organization_id = $1
              )::int AS contracts,

              (
                SELECT COUNT(*)
                FROM organization_opportunities
                WHERE organization_id = $1
              )::int AS opportunities,

              (
                SELECT COUNT(*)
                FROM organization_advertising_requests
                WHERE organization_id = $1
              )::int AS advertising_requests
          `,
          [organizationId]
        );


      const usage =
        usageResult.rows[0] || {};


      const hasBusinessData =
        Number(usage.locations || 0) > 0 ||
        Number(usage.contracts || 0) > 0 ||
        Number(usage.opportunities || 0) > 0 ||
        Number(
          usage.advertising_requests || 0
        ) > 0;


      if (hasBusinessData) {

        return res
          .status(400)
          .send(`
            <div style="
              font-family:Arial,sans-serif;
              max-width:700px;
              margin:50px auto;
              line-height:1.6;
            ">

              <h2>
                Organization cannot be deleted
              </h2>

              <p>
                <strong>
                  ${escapeHtml(
                    organization.name
                  )}
                </strong>
                has historical or operational Vivid data.
              </p>

              <p>
                Leave this customer archived so
                locations, contracts, inventory,
                requests and reporting remain intact.
              </p>

              <a
                href="/org-organizations?status=archived"
              >
                Back to Archived Organizations
              </a>

            </div>
          `);
      }


      /*
      Remove access relationships first.
      These contain access configuration,
      not business performance/history.
      */

      await q(
        `
          DELETE FROM location_users
          WHERE organization_id = $1
        `,
        [organizationId]
      );


      await q(
        `
          DELETE FROM organization_users
          WHERE organization_id = $1
        `,
        [organizationId]
      );


      /*
      Now remove the empty/test Organization.
      */

      await q(
        `
          DELETE FROM organizations
          WHERE id = $1
        `,
        [organizationId]
      );


      return res.redirect(
        "/org-organizations?status=archived"
      );


    } catch (err) {

      console.error(
        "DELETE ORGANIZATION ERROR:",
        err
      );

      return res
        .status(500)
        .send(
          "Unable to delete organization. " +
          "If this customer has related Vivid data, archive it instead. " +
          err.message
        );
    }
  }
);
async function buildOrganizationExportData(
  req,
  organizationId,
  fromDate = "",
  toDate = "",
  locationId = ""
) {
  const orgId = Number(organizationId);

  const scope =
    await getOrganizationScope(req);

  if (scope.organizationId !== orgId) {
    throw new Error("Access denied");
  }

  const selectedLocationId =
    locationId && Number.isInteger(Number(locationId))
      ? Number(locationId)
      : null;

  const allowedLocationIds =
    selectedLocationId
      ? [selectedLocationId]
      : scope.allowedLocationIds;
  if (!Number.isInteger(orgId) || orgId <= 0) {
    throw new Error("Valid organization is required.");
  }

  const organizationResult = await q(
    `
      SELECT
        id,
        name,
        organization_type,
        is_active
      FROM organizations
      WHERE id = $1
      LIMIT 1
    `,
    [orgId]
  );

  const organization = organizationResult.rows[0];

  if (!organization) {
    throw new Error("Organization not found.");
  }
/*
=========================================================
APPROVED OPPORTUNITIES — INTERNAL REVENUE
Read-only. No data is changed.
=========================================================
*/

const approvedResult = await q(
  `
    SELECT
      r.id AS request_id,
      r.organization_id,
      r.location_id,
      r.opportunity_id,
      r.business_name AS advertiser,
      r.opportunity_name,
      r.price AS approved_price,
      r.pricing_unit,
      r.status,
      r.approved_at,

      s.name AS location_name,
      s.location AS market

    FROM organization_advertising_requests r

    JOIN spaces s
      ON s.id = r.location_id
     AND s.organization_id = r.organization_id

    WHERE r.organization_id = $1
      AND LOWER(TRIM(COALESCE(r.status, ''))) = 'approved'
AND r.location_id = ANY($4::int[])

      AND (
        NULLIF($2, '') IS NULL
        OR r.approved_at::date >= NULLIF($2, '')::date
      )

      AND (
        NULLIF($3, '') IS NULL
        OR r.approved_at::date <= NULLIF($3, '')::date
      )

    ORDER BY
      r.approved_at DESC NULLS LAST,
      r.id DESC
  `,
[
  orgId,
  fromDate || "",
  toDate || "",
  allowedLocationIds
]
);

const approvedOpportunities =
  approvedResult.rows.map(row => ({
    requestId: Number(row.request_id),

    organizationId:
      Number(row.organization_id),

    locationId:
      Number(row.location_id),

    opportunityId:
      row.opportunity_id
        ? Number(row.opportunity_id)
        : null,

    advertiser:
      row.advertiser || "",

    opportunityName:
      row.opportunity_name || "",

    locationName:
      row.location_name || "",

    market:
      row.market || "",

    approvedPrice:
      Number(row.approved_price || 0),

    pricingUnit:
      row.pricing_unit || "",

    status:
      row.status || "Approved",

    approvedAt:
      row.approved_at || null
  }));
  /*
=========================================================
PENDING OPPORTUNITIES
Read-only. Uses the latest request for each opportunity.
=========================================================
*/

const pendingResult = await q(
  `
    WITH latest_requests AS (
      SELECT DISTINCT ON (r.opportunity_id)
        r.id AS request_id,
        r.organization_id,
        r.location_id,
        r.opportunity_id,
        r.business_name AS advertiser,
        r.opportunity_name,
        r.status,
        r.submitted_at,

        COALESCE(
          NULLIF(r.price, 0),
          NULLIF(oo.price, 0),
          oo.annual_price,
          0
        )::numeric AS pending_price,

        s.name AS location_name,
        s.location AS market

      FROM organization_advertising_requests r

      JOIN spaces s
        ON s.id = r.location_id
       AND s.organization_id = r.organization_id

      LEFT JOIN organization_opportunities oo
        ON oo.id = r.opportunity_id
       AND oo.organization_id = r.organization_id

      WHERE r.organization_id = $1

 AND r.location_id = ANY($2::int[])

      ORDER BY
        r.opportunity_id,
        r.created_at DESC,
        r.id DESC
    )

    SELECT *
    FROM latest_requests

    WHERE LOWER(
      TRIM(
        COALESCE(status, '')
      )
    ) = 'pending'

    ORDER BY
      submitted_at DESC NULLS LAST,
      request_id DESC
  `,
 [
  orgId,
  allowedLocationIds
]
);

const pendingOpportunities =
  pendingResult.rows.map(row => ({
    requestId:
      Number(row.request_id),

    organizationId:
      Number(row.organization_id),

    locationId:
      Number(row.location_id),

    opportunityId:
      row.opportunity_id
        ? Number(row.opportunity_id)
        : null,

    advertiser:
      row.advertiser || "",

    opportunityName:
      row.opportunity_name || "",

    locationName:
      row.location_name || "",

    market:
      row.market || "",

    pendingPrice:
      Number(row.pending_price || 0),

    status:
      row.status || "Pending",

    submittedAt:
      row.submitted_at || null
  }));

const pendingRevenue =
  pendingOpportunities.reduce(
    (total, row) =>
      total +
      Number(row.pendingPrice || 0),
    0
  );
  /*
=========================================================
AVAILABLE OPPORTUNITIES
Read-only
=========================================================
*/

const availableResult = await q(
`
SELECT
    oo.id,
    oo.space_id,
    oo.title,
    oo.status,

    COALESCE(
        NULLIF(oo.price,0),
        oo.annual_price,
        0
    )::numeric AS available_price,

    s.name AS location_name,
    s.location AS market

FROM organization_opportunities oo

JOIN spaces s
  ON s.id = oo.space_id
 AND s.organization_id = oo.organization_id

WHERE oo.organization_id = $1

AND oo.space_id = ANY($2::int[])

  AND LOWER(
        TRIM(
          COALESCE(oo.status,'')
        )
      )='available'

ORDER BY
    s.name,
    oo.title
`,
[
  orgId,
  allowedLocationIds
]
);

const availableOpportunities =
    availableResult.rows.map(r => ({
        opportunityId:Number(r.id),

        locationId:Number(r.space_id),

        opportunityName:r.title || "",

        locationName:r.location_name || "",

        market:r.market || "",

        availablePrice:Number(
            r.available_price || 0
        ),

        status:r.status || "Available"
    }));

const availableRevenue =
    availableOpportunities.reduce(
        (t,r)=>
            t+Number(
                r.availablePrice||0
            ),
        0
    );
  /*
=========================================================
LOCATION PERFORMANCE
=========================================================
*/

const locationsResult = await q(
`
SELECT

    s.id,
    s.name,
    s.location,

    COUNT(DISTINCT qr.id)::int AS placements,

    COUNT(DISTINCT c.id)::int AS campaigns,

    COUNT(DISTINCT LOWER(TRIM(c.advertiser)))
        FILTER (
            WHERE NULLIF(TRIM(c.advertiser),'') IS NOT NULL
        )::int AS advertisers,

    COUNT(e.id)
        FILTER (
            WHERE e.type='scan'
        )::int AS scans,

    COUNT(e.id)
        FILTER (
            WHERE e.type IN (
                'offer',
                'maps',
                'waze'
            )
        )::int AS intent,

    COUNT(e.id)
        FILTER (
            WHERE e.type='conversion'
        )::int AS conversions,

    COALESCE(
        SUM(e.value)
            FILTER (
                WHERE e.type='conversion'
            ),
        0
    )::numeric AS advertiser_revenue

FROM spaces s

LEFT JOIN qr_codes qr
    ON qr.space_id = s.id
   AND COALESCE(qr.is_archived, false) = false

LEFT JOIN qr_campaigns qc
    ON qc.qr_id=qr.id

LEFT JOIN campaigns c
    ON c.id=qc.campaign_id

LEFT JOIN events e
   
    ON e.qr_id = qr.id
   AND e.campaign_id = c.id

   AND (
     NULLIF($2, '') IS NULL
     OR e.created_at::date >= NULLIF($2, '')::date
   )

   AND (
     NULLIF($3, '') IS NULL
     OR e.created_at::date <= NULLIF($3, '')::date
   )

WHERE s.organization_id = $1
  AND COALESCE(s.is_archived, false) = false

  AND s.id = ANY($4::int[])
GROUP BY
    s.id,
    s.name,
    s.location

ORDER BY
    s.name
`,
[
  orgId,
  fromDate || "",
  toDate || "",
  allowedLocationIds
]
);
  const internalRevenueByLocation =
    new Map();

approvedOpportunities.forEach(r=>{

    const current =
        internalRevenueByLocation.get(
            r.locationId
        ) || 0;

    internalRevenueByLocation.set(
        r.locationId,
        current +
        Number(
            r.approvedPrice || 0
        )
    );

});
  const locations =
    locationsResult.rows.map(r=>{

        const internalRevenue =
            Number(
                internalRevenueByLocation.get(
                    Number(r.id)
                ) || 0
            );

        const advertiserRevenue =
            Number(
                r.advertiser_revenue || 0
            );

        return{

            locationId:Number(r.id),

            locationName:r.name,

            market:r.location,

            placements:Number(
                r.placements || 0
            ),

            campaigns:Number(
                r.campaigns || 0
            ),

            advertisers:Number(
                r.advertisers || 0
            ),

            scans:Number(
                r.scans || 0
            ),

            intent:Number(
                r.intent || 0
            ),

            conversions:Number(
                r.conversions || 0
            ),

            internalRevenue,

            advertiserRevenue,

            economicImpact:
                internalRevenue +
                advertiserRevenue

        };

    });
  /*
=========================================================
QR PLACEMENT PERFORMANCE
=========================================================
*/

const placementsResult = await q(
`
SELECT

    qr.id,
    qr.name,

    s.id AS location_id,
    s.name AS location_name,
    s.location AS market,

    COALESCE(
        qr.total_cost,
        qr.annual_cost,
        0
    )::numeric AS placement_value,

    COUNT(DISTINCT c.id)::int AS campaigns,

    STRING_AGG(
        DISTINCT c.advertiser,
        ', '
    )
    FILTER(
        WHERE NULLIF(
            TRIM(c.advertiser),
            ''
        ) IS NOT NULL
    ) AS advertisers,

    COUNT(e.id)
        FILTER(
            WHERE e.type='scan'
        )::int AS scans,

    COUNT(e.id)
        FILTER(
            WHERE e.type IN(
                'offer',
                'maps',
                'waze'
            )
        )::int AS intent,

    COUNT(e.id)
        FILTER(
            WHERE e.type='conversion'
        )::int AS conversions,

    COALESCE(
        SUM(e.value)
            FILTER(
                WHERE e.type='conversion'
            ),
        0
    )::numeric AS advertiser_revenue

FROM qr_codes qr

JOIN spaces s
    ON s.id=qr.space_id
   AND s.organization_id=$1
  AND s.id = ANY($4::int[])

LEFT JOIN qr_campaigns qc
    ON qc.qr_id=qr.id

LEFT JOIN campaigns c
    ON c.id=qc.campaign_id

LEFT JOIN events e
    ON e.qr_id=qr.id
   AND e.campaign_id=c.id

   AND (
       NULLIF($2,'') IS NULL
       OR e.created_at::date>=NULLIF($2,'')::date
   )

   AND (
       NULLIF($3,'') IS NULL
       OR e.created_at::date<=NULLIF($3,'')::date
   )

WHERE
    COALESCE(
        qr.is_archived,
        false
    )=false

GROUP BY

    qr.id,
    qr.name,

    s.id,
    s.name,
    s.location,

    qr.total_cost,
    qr.annual_cost

ORDER BY

    s.name,
    qr.name
`,
[
  orgId,
  fromDate || "",
  toDate || "",
  allowedLocationIds
]

);
  const internalRevenueByQr =
    new Map();

approvedOpportunities.forEach(r=>{

    if(!r.qrId) return;

    const current =
        internalRevenueByQr.get(
            r.qrId
        ) || 0;

    internalRevenueByQr.set(

        r.qrId,

        current +
        Number(
            r.approvedPrice || 0
        )

    );

});
  const placements =
    placementsResult.rows.map(r=>{

        const qrId =
            Number(r.id);

        const internalRevenue =
            Number(
                internalRevenueByQr.get(
                    qrId
                ) || 0
            );

        const advertiserRevenue =
            Number(
                r.advertiser_revenue || 0
            );

        return{

            qrId,

            qrName:r.name,

            locationId:Number(
                r.location_id
            ),

            locationName:
                r.location_name,

            market:r.market,

            placementValue:Number(
                r.placement_value || 0
            ),

            internalRevenue,

            advertiserRevenue,

            economicImpact:
                internalRevenue +
                advertiserRevenue,

            campaigns:Number(
                r.campaigns || 0
            ),

            advertisers:
                r.advertisers || "",

            scans:Number(
                r.scans || 0
            ),

            intent:Number(
                r.intent || 0
            ),

            conversions:Number(
                r.conversions || 0
            )

        };

    });
  /*
=========================================================
CAMPAIGN PERFORMANCE
Read-only organization reporting
=========================================================
*/

const campaignsResult = await q(
  `
    WITH unique_assignments AS (
      SELECT DISTINCT
        qr_id,
        campaign_id
      FROM qr_campaigns
    )

    SELECT
      c.id AS campaign_id,
      c.name AS campaign_name,
      c.advertiser,

      COALESCE(
        c.is_archived,
        false
      ) AS is_archived,

      STRING_AGG(
        DISTINCT qr.name,
        ', '
      ) AS qr_names,

      STRING_AGG(
        DISTINCT s.name,
        ', '
      ) AS location_names,

      COUNT(e.id) FILTER (
        WHERE e.type = 'scan'
      )::int AS scans,

      COUNT(e.id) FILTER (
        WHERE e.type IN (
          'offer',
          'maps',
          'waze'
        )
      )::int AS intent,

      COUNT(e.id) FILTER (
        WHERE e.type = 'destination_click'
      )::int AS clicks,

      COUNT(
        DISTINCT e.vivid_click_id
      ) FILTER (
        WHERE e.type = 'destination_click'
          AND NULLIF(
                TRIM(e.vivid_click_id),
                ''
              ) IS NOT NULL
      )::int AS visitors,

      COUNT(e.id) FILTER (
        WHERE e.type = 'conversion'
      )::int AS conversions,

      COUNT(
        DISTINCT e.vivid_click_id
      ) FILTER (
        WHERE e.type = 'conversion'
          AND NULLIF(
                TRIM(e.vivid_click_id),
                ''
              ) IS NOT NULL
      )::int AS visitors_converted,

      COALESCE(
        SUM(e.value) FILTER (
          WHERE e.type = 'conversion'
        ),
        0
      )::numeric AS advertiser_revenue,

      MAX(e.created_at)
        AS last_activity

    FROM campaigns c

    JOIN unique_assignments qc
      ON qc.campaign_id = c.id

    JOIN qr_codes qr
      ON qr.id = qc.qr_id
     AND COALESCE(
           qr.is_archived,
           false
         ) = false

  JOIN spaces s
  ON s.id = qr.space_id
 AND s.organization_id = $1
 AND COALESCE(
       s.is_archived,
       false
     ) = false
AND s.id = ANY($4::int[])

    LEFT JOIN events e
      ON e.campaign_id = c.id
     AND e.qr_id = qr.id

     AND (
       NULLIF($2, '') IS NULL
       OR e.created_at::date >=
          NULLIF($2, '')::date
     )

     AND (
       NULLIF($3, '') IS NULL
       OR e.created_at::date <=
          NULLIF($3, '')::date
     )

    GROUP BY
      c.id,
      c.name,
      c.advertiser,
      c.is_archived

    ORDER BY
      c.advertiser,
      c.name
  `,
[
  orgId,
  fromDate || "",
  toDate || "",
  allowedLocationIds
]
);

const campaigns =
  campaignsResult.rows.map(row => {
    const visitors =
      Number(row.visitors || 0);

    const clicks =
      Number(row.clicks || 0);

    const conversions =
      Number(row.conversions || 0);

    const visitorsConverted =
      Number(
        row.visitors_converted || 0
      );

    const advertiserRevenue =
      Number(
        row.advertiser_revenue || 0
      );

    return {
      campaignId:
        Number(row.campaign_id),

      campaignName:
        row.campaign_name || "",

      advertiser:
        row.advertiser || "",

      qrNames:
        row.qr_names || "",

      locationNames:
        row.location_names || "",

      status:
        row.is_archived
          ? "Archived"
          : "Active",

      scans:
        Number(row.scans || 0),

      intent:
        Number(row.intent || 0),

      visitors,

      clicks,

      conversions,

      visitorsConverted,

      visitorConversionRate:
        visitors > 0
          ? (
              visitorsConverted /
              visitors
            ) * 100
          : 0,

      advertiserRevenue,

      revenuePerVisitor:
        visitors > 0
          ? advertiserRevenue /
            visitors
          : 0,

      revenuePerClick:
        clicks > 0
          ? advertiserRevenue /
            clicks
          : 0,

      revenuePerConversion:
        conversions > 0
          ? advertiserRevenue /
            conversions
          : 0,

      lastActivity:
        row.last_activity || null
    };
  });
  /*
=========================================================
ADVERTISER PERFORMANCE
Built from campaign rows already loaded above
=========================================================
*/

/*
=========================================================
ADVERTISER PERFORMANCE
Built from campaign and approved-opportunity data
=========================================================
*/

const approvedRevenueByAdvertiser =
  new Map();

approvedOpportunities.forEach(row => {
  const key = String(
    row.advertiser || ""
  )
    .trim()
    .toLowerCase();

  if (!key) {
    return;
  }

  const current =
    approvedRevenueByAdvertiser.get(
      key
    ) || 0;

  approvedRevenueByAdvertiser.set(
    key,
    current +
      Number(
        row.approvedPrice || 0
      )
  );
});

const advertiserMap =
  new Map();

campaigns.forEach(campaign => {
  const key = String(
    campaign.advertiser || ""
  )
    .trim()
    .toLowerCase();

  if (!key) {
    return;
  }

  if (!advertiserMap.has(key)) {
    advertiserMap.set(key, {
      advertiser:
        campaign.advertiser || "",

      campaigns: 0,

      locationNames:
        new Set(),

      scans: 0,
      intent: 0,
      visitors: 0,
      clicks: 0,
      conversions: 0,
      advertiserRevenue: 0
    });
  }

  const advertiser =
    advertiserMap.get(key);

  advertiser.campaigns += 1;

  String(
    campaign.locationNames || ""
  )
    .split(",")
    .map(value => value.trim())
    .filter(Boolean)
    .forEach(locationName => {
      advertiser.locationNames.add(
        locationName
      );
    });

  advertiser.scans +=
    Number(campaign.scans || 0);

  advertiser.intent +=
    Number(campaign.intent || 0);

  advertiser.visitors +=
    Number(campaign.visitors || 0);

  advertiser.clicks +=
    Number(campaign.clicks || 0);

  advertiser.conversions +=
    Number(
      campaign.conversions || 0
    );

  advertiser.advertiserRevenue +=
    Number(
      campaign.advertiserRevenue || 0
    );
});

const advertisers =
  Array.from(
    advertiserMap.entries()
  )
    .map(([key, advertiser]) => {
      const internalRevenue =
        Number(
          approvedRevenueByAdvertiser.get(
            key
          ) || 0
        );

      const advertiserRevenue =
        Number(
          advertiser.advertiserRevenue ||
          0
        );

      return {
        advertiser:
          advertiser.advertiser,

        campaigns:
          advertiser.campaigns,

        locations:
          advertiser.locationNames.size,

        scans:
          advertiser.scans,

        intent:
          advertiser.intent,

        visitors:
          advertiser.visitors,

        clicks:
          advertiser.clicks,

        conversions:
          advertiser.conversions,

        advertiserRevenue,

        internalRevenue,

        economicImpact:
          internalRevenue +
          advertiserRevenue,

        conversionRate:
          advertiser.visitors > 0
            ? (
                advertiser.conversions /
                advertiser.visitors
              ) * 100
            : 0,

        revenuePerVisitor:
          advertiser.visitors > 0
            ? advertiserRevenue /
              advertiser.visitors
            : 0,

        revenuePerClick:
          advertiser.clicks > 0
            ? advertiserRevenue /
              advertiser.clicks
            : 0,

        revenuePerConversion:
          advertiser.conversions > 0
            ? advertiserRevenue /
              advertiser.conversions
            : 0
      };
    })
    .sort(
      (a, b) =>
        b.economicImpact -
        a.economicImpact
    );
 /*
=========================================================
CUSTOMER ACTION PERFORMANCE
Read-only organization reporting
=========================================================
*/

const customerActionsResult = await q(
  `
    SELECT
      cd.id AS customer_action_id,
      cd.campaign_id,
      cd.name AS customer_action_name,
      cd.destination_type,
      cd.destination_url,
      cd.conversion_url,
      cd.estimated_value,
      cd.display_order,
      cd.is_active,

      c.name AS campaign_name,
      c.advertiser,

      STRING_AGG(
        DISTINCT qr.name,
        ', '
      ) AS qr_names,

      STRING_AGG(
        DISTINCT s.name,
        ', '
      ) AS location_names,

      COUNT(e.id) FILTER (
        WHERE e.type = 'destination_click'
      )::int AS clicks,

      COUNT(
        DISTINCT e.vivid_click_id
      ) FILTER (
        WHERE e.type = 'destination_click'
          AND NULLIF(
                TRIM(e.vivid_click_id),
                ''
              ) IS NOT NULL
      )::int AS visitors,

      COUNT(e.id) FILTER (
        WHERE e.type = 'conversion'
      )::int AS conversions,

      COUNT(
        DISTINCT e.vivid_click_id
      ) FILTER (
        WHERE e.type = 'conversion'
          AND NULLIF(
                TRIM(e.vivid_click_id),
                ''
              ) IS NOT NULL
      )::int AS visitors_converted,

      COALESCE(
        SUM(e.value) FILTER (
          WHERE e.type = 'conversion'
        ),
        0
      )::numeric AS advertiser_revenue,

      MAX(e.created_at) AS last_activity

    FROM campaign_destinations cd

    JOIN campaigns c
      ON c.id = cd.campaign_id

    JOIN qr_campaigns qc
      ON qc.campaign_id = c.id

    JOIN qr_codes qr
      ON qr.id = qc.qr_id
     AND COALESCE(
           qr.is_archived,
           false
         ) = false

    JOIN spaces s
  ON s.id = qr.space_id
 AND s.organization_id = $1
 AND COALESCE(
       s.is_archived,
       false
     ) = false
AND s.id = ANY($4::int[])
    LEFT JOIN events e
      ON e.campaign_destination_id = cd.id
     AND e.campaign_id = c.id
     AND e.qr_id = qr.id

     AND (
       NULLIF($2, '') IS NULL
       OR e.created_at::date >=
          NULLIF($2, '')::date
     )

     AND (
       NULLIF($3, '') IS NULL
       OR e.created_at::date <=
          NULLIF($3, '')::date
     )

    GROUP BY
      cd.id,
      cd.campaign_id,
      cd.name,
      cd.destination_type,
      cd.destination_url,
      cd.conversion_url,
      cd.estimated_value,
      cd.display_order,
      cd.is_active,
      c.name,
      c.advertiser

    ORDER BY
      c.advertiser,
      c.name,
      cd.display_order,
      cd.id
  `,
[
  orgId,
  fromDate || "",
  toDate || "",
  allowedLocationIds
]
);

const customerActions =
  customerActionsResult.rows.map(row => {
    const visitors =
      Number(row.visitors || 0);

    const clicks =
      Number(row.clicks || 0);

    const conversions =
      Number(row.conversions || 0);

    const visitorsConverted =
      Number(
        row.visitors_converted || 0
      );

    const advertiserRevenue =
      Number(
        row.advertiser_revenue || 0
      );

    return {
      customerActionId:
        Number(row.customer_action_id),

      campaignId:
        Number(row.campaign_id),

      campaignName:
        row.campaign_name || "",

      advertiser:
        row.advertiser || "",

      customerActionName:
        row.customer_action_name || "",

      destinationType:
        row.destination_type || "website",

      destinationUrl:
        row.destination_url || "",

      conversionUrl:
        row.conversion_url || "",

      estimatedValue:
        Number(
          row.estimated_value || 0
        ),

      displayOrder:
        Number(
          row.display_order || 0
        ),

      status:
        row.is_active
          ? "Active"
          : "Inactive",

      qrNames:
        row.qr_names || "",

      locationNames:
        row.location_names || "",

      visitors,

      clicks,

      conversions,

      visitorsConverted,

      conversionRate:
        visitors > 0
          ? (
              visitorsConverted /
              visitors
            ) * 100
          : 0,

      advertiserRevenue,

      revenuePerVisitor:
        visitors > 0
          ? advertiserRevenue /
            visitors
          : 0,

      revenuePerClick:
        clicks > 0
          ? advertiserRevenue /
            clicks
          : 0,

      revenuePerConversion:
        conversions > 0
          ? advertiserRevenue /
            conversions
          : 0,

      lastActivity:
        row.last_activity || null
    };
  }); 
  const approvedRevenue =
  approvedOpportunities.reduce(
    (total, row) =>
      total +
      Number(
        row.approvedPrice || 0
      ),
    0
  );

const advertiserRevenue =
  campaigns.reduce(
    (total, row) =>
      total +
      Number(
        row.advertiserRevenue || 0
      ),
    0
  );

const visitors =
  campaigns.reduce(
    (total, row) =>
      total +
      Number(row.visitors || 0),
    0
  );

const clicks =
  campaigns.reduce(
    (total, row) =>
      total +
      Number(row.clicks || 0),
    0
  );

const scans =
  campaigns.reduce(
    (total, row) =>
      total +
      Number(row.scans || 0),
    0
  );

const intent =
  campaigns.reduce(
    (total, row) =>
      total +
      Number(row.intent || 0),
    0
  );

const conversions =
  campaigns.reduce(
    (total, row) =>
      total +
      Number(row.conversions || 0),
    0
  );

const placementValue =
  placements.reduce(
    (total, row) =>
      total +
      Number(
        row.placementValue || 0
      ),
    0
  );

const summary = {
  locations:
    locations.length,

  placements:
    placements.length,

  advertisers:
    advertisers.length,

  campaigns:
    campaigns.length,

  customerActions:
    customerActions.length,

  approvedSpots:
    approvedOpportunities.length,

  approvedRevenue,

  pendingSpots:
    pendingOpportunities.length,

  pendingRevenue,

  availableSpots:
    availableOpportunities.length,

  availableRevenue,

  placementValue,

  visitors,

  clicks,

  scans,

  intent,

  conversions,

  advertiserRevenue,

  economicImpact:
    approvedRevenue +
    advertiserRevenue,

  conversionRate:
    visitors > 0
      ? (
          conversions /
          visitors
        ) * 100
      : 0,

  revenuePerAdvertiser:
    advertisers.length > 0
      ? approvedRevenue /
        advertisers.length
      : 0,

  revenuePerLocation:
    locations.length > 0
      ? approvedRevenue /
        locations.length
      : 0,

  inventoryUtilization:
    (
      approvedOpportunities.length +
      availableOpportunities.length
    ) > 0
      ? (
          approvedOpportunities.length /
          (
            approvedOpportunities.length +
            availableOpportunities.length
          )
        ) * 100
      : 0
};

  return {
    organization,

    reportingPeriod: {
      fromDate: fromDate || null,
      toDate: toDate || null
    },

    summary,

    locations,
    placements,
    advertisers,
    campaigns,
    customerActions,
    approvedOpportunities,
    pendingOpportunities,
    availableOpportunities,
  };
}
