app.get(
  "/org-users/new",
  requireOrganizationPermission("manage_users"),
  async (req, res) => {
    try {
      const organizationId = Number(
        req.session.orgUser.organization_id
      );

      if (
        !Number.isInteger(organizationId) ||
        organizationId <= 0
      ) {
        return res
          .status(400)
          .send("Valid organization is required.");
      }

      const organizationResult = await q(
        `
          SELECT
            id,
            name
          FROM organizations
          WHERE id = $1
            AND COALESCE(is_active, true) = true
          LIMIT 1
        `,
        [organizationId]
      );

      const organization =
        organizationResult.rows[0];

      if (!organization) {
        return res
          .status(404)
          .send("Organization not found.");
      }

      const locationsResult = await q(
  `
    SELECT
      id,
      name,
      location
    FROM (
      SELECT
        s.id,
        s.name,
        s.location,

        ROW_NUMBER() OVER (
          PARTITION BY
            LOWER(TRIM(s.name)),
            LOWER(
              TRIM(
                COALESCE(s.location, '')
              )
            )
          ORDER BY s.id ASC
        ) AS duplicate_number

      FROM spaces s

      WHERE s.organization_id = $1
        AND COALESCE(s.is_archived, false) = false
    ) locations

    WHERE duplicate_number = 1

    ORDER BY name ASC
  `,
  [organizationId]
);
    
  

      const locationOptions =
        locationsResult.rows
          .map((location) => {
            const locationDescription =
              location.location
                ? ` — ${escapeHtml(location.location)}`
                : "";

            return `
              <label style="
                display:flex;
                align-items:flex-start;
                gap:10px;
                padding:12px;
                margin:0;
                border:1px solid #DCE5DC;
                border-radius:10px;
                background:#FFFFFF;
                cursor:pointer;
              ">
                <input
                  type="checkbox"
                  name="location_ids"
                  value="${location.id}"
                  style="
                    width:auto;
                    margin-top:3px;
                  "
                />

                <span>
                  <strong>
                    ${escapeHtml(location.name)}
                  </strong>

                  <span style="
                    color:#64748B;
                    font-size:13px;
                  ">
                    ${locationDescription}
                  </span>
                </span>
              </label>
            `;
          })
          .join("");

      res.send(
        orgPage(
          `Add ${organization.name} User`,
          `
            <div class="topbar">
              <div class="brand">
                Vivid Organizations
              </div>

              <h1>Add User</h1>

              <p class="subtitle">
                Give a team member access to
                ${escapeHtml(organization.name)}.
              </p>
            </div>

            <div class="wrap">

              <div style="margin-bottom:20px;">
                <a
                  class="btn secondary"
                  href="/org-users"
                >
                  Back to Users
                </a>
              </div>

              <form
                method="POST"
                action="/org-users"
              >
                <div class="card">

                  <h2 style="margin-top:0;">
                    User Information
                  </h2>

                  <label for="name">
                    Full Name
                  </label>

                  <input
                    id="name"
                    name="name"
                    type="text"
                    maxlength="150"
                    required
                  />

                  <label for="email">
                    Email Address
                  </label>

                  <input
                    id="email"
                    name="email"
                    type="email"
                    maxlength="255"
                    required
                  />

                  <div style="
  background:#F0FDF4;
  border-left:5px solid #16A34A;
  padding:16px;
  border-radius:10px;
  margin:10px 0 18px;
  line-height:1.5;
">
  <strong>Account Setup Email</strong>

  <p style="margin:6px 0 0;">
    Vivid will email this user a secure link so they can
    create their own password and access the Organization Portal.
  </p>
</div>

                  <label for="role">
                    Role
                  </label>

                  <select
                    id="role"
                    name="role"
                    required
                    onchange="updateLocationVisibility()"
                  >
                    <option value="">
                      Select a role
                    </option>

                    <option value="organization_admin">
                      Organization Administrator
                    </option>

                    <option value="location_manager">
                      Location Manager
                    </option>

                    <option value="standard_user">
                      Standard User
                    </option>

                    <option value="read_only">
                      Read Only
                    </option>
                  </select>

                </div>

                <div
                  id="locationAssignmentCard"
                  class="card"
                  style="
                    margin-top:20px;
                    display:none;
                  "
                >
                  <h2 style="margin-top:0;">
                    Location Access
                  </h2>

                  <p style="
                    color:#64748B;
                    margin-bottom:18px;
                  ">
                    Select every location this user
                    should be able to access.
                  </p>

                  <div style="
                    display:grid;
                    grid-template-columns:
                      repeat(auto-fit, minmax(260px, 1fr));
                    gap:10px;
                  ">
                    ${
                      locationOptions ||
                      `
                        <p style="color:#64748B;">
                          No active locations are available.
                        </p>
                      `
                    }
                  </div>
                </div>

                <div style="
                  display:flex;
                  justify-content:flex-end;
                  gap:12px;
                  margin-top:20px;
                ">
                  <a
                    class="btn secondary"
                    href="/org-users"
                  >
                    Cancel
                  </a>

                  <button
                    class="btn"
                    type="submit"
                  >
                    Add User
                  </button>
                </div>

              </form>
            </div>

            <script>
              function updateLocationVisibility() {
                const role =
                  document.getElementById("role").value;

                const locationCard =
                  document.getElementById(
                    "locationAssignmentCard"
                  );

                const requiresLocations = [
                  "location_manager",
                  "standard_user",
                  "read_only"
                ].includes(role);

                locationCard.style.display =
                  requiresLocations
                    ? "block"
                    : "none";

                if (!requiresLocations) {
                  document
                    .querySelectorAll(
                      'input[name="location_ids"]'
                    )
                    .forEach((checkbox) => {
                      checkbox.checked = false;
                    });
                }
              }

              updateLocationVisibility();
            </script>
          `
        )
      );
    } catch (err) {
      console.error(
        "ADD ORGANIZATION USER FORM ERROR:",
        err
      );

      res.status(500).send(
        "ADD ORGANIZATION USER FORM ERROR: " +
          err.message
      );
    }
  }
);
/*
=========================================================
SAVE ORGANIZATION USER
=========================================================
*/

app.post(
  "/org-users",
  requireOrganizationPermission("manage_users"),
  async (req, res) => {
    const client = await pool.connect();

    try {
      const organizationId = Number(
        req.session.orgUser.organization_id
      );

      const name = String(
        req.body.name || ""
      ).trim();

      const email = String(
        req.body.email || ""
      )
        .trim()
        .toLowerCase();

      
        
      

      const role = String(
        req.body.role || ""
      )
        .trim()
        .toLowerCase();

      /*
        Express returns either:

        - one string when one checkbox is selected
        - an array when several are selected
        - undefined when none are selected

        Normalize all three possibilities into an array.
      */
      const submittedLocationIds =
        req.body.location_ids === undefined
          ? []
          : Array.isArray(req.body.location_ids)
            ? req.body.location_ids
            : [req.body.location_ids];

      const locationIds = [
        ...new Set(
          submittedLocationIds
            .map(value => Number(value))
            .filter(
              value =>
                Number.isInteger(value) &&
                value > 0
            )
        )
      ];

      /*
      =====================================================
      VALIDATION
      =====================================================
      */

      if (
        !Number.isInteger(organizationId) ||
        organizationId <= 0
      ) {
        return res
          .status(400)
          .send("Valid organization is required.");
      }

      if (!name) {
        return res
          .status(400)
          .send(`
            Full Name is required.
            <br><br>
            <a href="/org-users/new">Back to Add User</a>
          `);
      }

      if (
        !email ||
        !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
      ) {
        return res
          .status(400)
          .send(`
            A valid email address is required.
            <br><br>
            <a href="/org-users/new">Back to Add User</a>
          `);
      }

      const allowedRoles = [
        "organization_admin",
        "location_manager",
        "standard_user",
        "read_only"
      ];

      if (!allowedRoles.includes(role)) {
        return res
          .status(400)
          .send(`
            A valid organization role is required.
            <br><br>
            <a href="/org-users/new">Back to Add User</a>
          `);
      }

      const requiresLocations = [
        "location_manager",
        "standard_user",
        "read_only"
      ].includes(role);

      if (
        requiresLocations &&
        locationIds.length === 0
      ) {
        return res
          .status(400)
          .send(`
            Select at least one location for this role.
            <br><br>
            <a href="/org-users/new">Back to Add User</a>
          `);
      }

      

      await client.query("BEGIN");

      /*
      =====================================================
      CONFIRM ORGANIZATION
      =====================================================
      */

      const organizationResult =
        await client.query(
          `
            SELECT
              id,
              name
            FROM organizations
            WHERE id = $1
              AND COALESCE(is_active, true) = true
            LIMIT 1
          `,
          [organizationId]
        );

      const organization =
        organizationResult.rows[0];

      if (!organization) {
        await client.query("ROLLBACK");

        return res
          .status(404)
          .send("Organization not found.");
      }

      /*
      =====================================================
      VALIDATE LOCATION OWNERSHIP
      =====================================================

      Do not trust location IDs submitted by the browser.
      Every selected location must belong to this organization.
      */

      if (requiresLocations) {
        const validLocationsResult =
          await client.query(
            `
              SELECT id
              FROM spaces
              WHERE organization_id = $1
                AND id = ANY($2::int[])
                AND COALESCE(is_archived, false) = false
            `,
            [
              organizationId,
              locationIds
            ]
          );

        const validLocationIds =
          validLocationsResult.rows.map(
            row => Number(row.id)
          );

        if (
          validLocationIds.length !==
          locationIds.length
        ) {
          await client.query("ROLLBACK");

          return res
            .status(400)
            .send(`
              One or more selected locations are invalid.
              <br><br>
              <a href="/org-users/new">Back to Add User</a>
            `);
        }
      }

      const existingUserResult =
  await client.query(
    `
      SELECT
        id,
        name,
        email,
        account_status
      FROM users
      WHERE LOWER(TRIM(email)) =
            LOWER(TRIM($1))
      LIMIT 1
      FOR UPDATE
    `,
    [email]
  );

let userId = null;
let existingVividUser = false;

if (existingUserResult.rows.length > 0) {
  userId = Number(
    existingUserResult.rows[0].id
  );

  existingVividUser = true;
} else {
  const newUserResult =
    await client.query(
      `
        INSERT INTO users (
          name,
          email,
          password,
          role,
          account_status
        )
        VALUES (
          $1,
          $2,
          NULL,
          'organization_user',
          'pending'
        )
        RETURNING id
      `,
      [
        name,
        email
      ]
    );

  if (
    !newUserResult.rows.length ||
    !newUserResult.rows[0].id
  ) {
    throw new Error(
      "Unable to create Vivid user."
    );
  }

  userId = Number(
    newUserResult.rows[0].id
  );
}

if (
  !Number.isInteger(userId) ||
  userId <= 0
) {
  throw new Error(
    "User ID was not created."
  );
}


      const existingMembershipResult =
        await client.query(
          `
            SELECT
              id,
              is_active
            FROM organization_users
            WHERE organization_id = $1
              AND user_id = $2
            LIMIT 1
            FOR UPDATE
          `,
          [
            organizationId,
            userId
          ]
        );

      if (existingMembershipResult.rows.length) {
        await client.query("ROLLBACK");

        const membership =
          existingMembershipResult.rows[0];

        const membershipMessage =
          membership.is_active
            ? `${escapeHtml(email)} already belongs to ${escapeHtml(
                organization.name
              )}.`
            : `${escapeHtml(email)} previously belonged to ${escapeHtml(
                organization.name
              )} and is currently inactive. Use Edit User to reactivate the account.`;

        return res
          .status(409)
          .send(`
            <div style="
              max-width:650px;
              margin:50px auto;
              padding:28px;
              font-family:Arial,sans-serif;
            ">
              <h2>User Already Connected</h2>

              <p>
                ${membershipMessage}
              </p>

              <a href="/org-users">
                Back to Users
              </a>
            </div>
          `);
      }

      /*
      =====================================================
      CREATE ORGANIZATION MEMBERSHIP
      =====================================================
      */

      const membershipResult =
        await client.query(
          `
            INSERT INTO organization_users (
              organization_id,
              user_id,
              role,
              is_active
            )
            VALUES (
              $1,
              $2,
              $3,
              true
            )
            RETURNING id
          `,
          [
            organizationId,
            userId,
            role
          ]
        );

      const organizationUserId =
        Number(
          membershipResult.rows[0].id
        );

      /*
      =====================================================
      CREATE LOCATION ACCESS
      =====================================================

      Organization Administrators receive organization-wide
      access through their role and do not require rows in
      location_users.
      */

      if (requiresLocations) {
        const locationRole =
          role === "location_manager"
            ? "manager"
            : role === "standard_user"
              ? "standard_user"
              : "read_only";

        const canManage =
          role === "location_manager";

        const canViewReports =
          role !== "read_only";

        for (const spaceId of locationIds) {
          await client.query(
            `
              INSERT INTO location_users (
                organization_id,
                space_id,
                user_id,
                role,
                can_manage_contracts,
                can_manage_pricing,
                can_view_reports,
                is_active
              )
              VALUES (
                $1,
                $2,
                $3,
                $4,
                $5,
                $6,
                $7,
                true
              )
            `,
            [
              organizationId,
              spaceId,
              userId,
              locationRole,
              canManage,
              canManage,
              canViewReports
            ]
          );
        }
      }

      /*
      =====================================================
      CREATE DEFAULT NOTIFICATION PREFERENCES
      =====================================================
      */

      const defaultNotifications = [
        "advertising_request_submitted",
        "advertising_request_approved",
        "contract_expiring",
        "campaign_started",
        "campaign_ended"
      ];

      for (
        const notificationKey
        of defaultNotifications
      ) {
        await client.query(
          `
            INSERT INTO organization_user_notifications (
              organization_user_id,
              notification_key,
              is_enabled
            )
            VALUES (
              $1,
              $2,
              true
            )
            ON CONFLICT (
              organization_user_id,
              notification_key
            )
            DO NOTHING
          `,
          [
            organizationUserId,
            notificationKey
          ]
        );
      }
/*
=====================================================
CREATE ORGANIZATION USER INVITATION
=====================================================
*/

const rawInvitationToken =
  crypto.randomBytes(32).toString("hex");

const invitationTokenHash =
  crypto
    .createHash("sha256")
    .update(rawInvitationToken)
    .digest("hex");

const invitationExpiresAt =
  new Date(
    Date.now() +
    7 * 24 * 60 * 60 * 1000
  );

const invitedByUserId =
  req.session.orgUser?.user_id
    ? Number(req.session.orgUser.user_id)
    : null;

/*
  Revoke any previous unused invitations for this
  organization and user before creating a new one.
*/
await client.query(
  `
    UPDATE organization_user_invitations

    SET revoked_at = CURRENT_TIMESTAMP

    WHERE organization_id = $1
      AND user_id = $2
      AND accepted_at IS NULL
      AND revoked_at IS NULL
  `,
  [
    organizationId,
    userId
  ]
);

await client.query(
  `
    INSERT INTO organization_user_invitations (
      organization_id,
      user_id,
      organization_user_id,
      invited_by_user_id,
      email,
      token_hash,
      expires_at
    )
    VALUES (
      $1,
      $2,
      $3,
      $4,
      $5,
      $6,
      $7
    )
  `,
  [
    organizationId,
    userId,
    organizationUserId,
    invitedByUserId,
    email,
    invitationTokenHash,
    invitationExpiresAt
  ]
);

const invitationUrl =
  `${BASE_URL}/org-invitation/${rawInvitationToken}`;
      await client.query("COMMIT");

      /*
      =====================================================
      SUCCESS
      =====================================================
      */

      return res.send(
        orgPage(
          "Organization User Added",
          `
            <div class="topbar">
              <div class="brand">
                Vivid Organizations
              </div>

              <h1>User Added</h1>

              <p class="subtitle">
                Organization access was created successfully.
              </p>
            </div>

            <div class="wrap">
              <div
                class="card"
                style="
                  max-width:700px;
                  margin:30px auto;
                "
              >
                <h2 style="margin-top:0;">
                  ${escapeHtml(name)}
                </h2>

                <p>
                  <strong>Email:</strong>
                  ${escapeHtml(email)}
                </p>

                <p>
                  <strong>Organization:</strong>
                  ${escapeHtml(organization.name)}
                </p>

                <p>
                  <strong>Role:</strong>
                  ${escapeHtml(
                    role
                      .split("_")
                      .map(
                        word =>
                          word.charAt(0).toUpperCase() +
                          word.slice(1)
                      )
                      .join(" ")
                  )}
                </p>

                ${
                  existingVividUser
                    ? `
                      <div
                        style="
                          background:#EFF6FF;
                          border-left:5px solid #2563EB;
                          padding:16px;
                          border-radius:10px;
                          margin:20px 0;
                        "
                      >
                        <strong>
                          Existing Vivid account connected
                        </strong>

                        <p style="margin-bottom:0;">
                          This person already had a Vivid
                          account. Their existing password
                          was preserved, and access to
                          ${escapeHtml(organization.name)}
                          was added.
                        </p>
                      </div>
                    `
                    : `
              <div
  style="
    background:#ECFDF5;
    border-left:5px solid #16A34A;
    padding:16px;
    border-radius:10px;
    margin:20px 0;
  "
>
  <strong>
    Invitation Created
  </strong>

  <p>
    A secure account setup invitation has been
    created for ${escapeHtml(email)}.
  </p>

  <p style="margin-bottom:8px;">
    Email delivery will be connected next.
  </p>

  <a
    href="${invitationUrl}"
    style="
      display:inline-block;
      margin-top:8px;
      overflow-wrap:anywhere;
    "
  >
    Open Account Setup Link
  </a>
</div>        
                    `
                }

                <div style="
                  display:flex;
                  gap:12px;
                  flex-wrap:wrap;
                  margin-top:24px;
                ">
                  <a
                    class="btn"
                    href="/org-users"
                  >
                    Back to Users
                  </a>

                  <a
                    class="btn secondary"
                    href="/org-users/new"
                  >
                    Add Another User
                  </a>
                </div>
              </div>
            </div>
          `
        )
      );
    } catch (err) {
      try {
        await client.query("ROLLBACK");
      } catch (rollbackErr) {
        console.error(
          "ORGANIZATION USER ROLLBACK ERROR:",
          rollbackErr
        );
      }

      console.error(
        "SAVE ORGANIZATION USER ERROR:",
        err
      );

      if (err.code === "23505") {
        return res
          .status(409)
          .send(`
            This user or location assignment already exists.
            <br><br>
            <a href="/org-users">Back to Users</a>
          `);
      }

      return res
        .status(500)
        .send(
          "SAVE ORGANIZATION USER ERROR: " +
            err.message
        );
    } finally {
      client.release();
    }
  }
);
app.get(
  "/org-users",
  requireOrganizationPermission("manage_users"),
  async (req, res) => {
    try {
     let organizationId = null;

if (
  req.session.user?.role === "super_admin"
) {
  organizationId = Number(
    req.query.organization_id
  );
}

if (
  !organizationId &&
  req.session.orgUser?.organization_id
) {
  organizationId = Number(
    req.session.orgUser.organization_id
  );
}

      if (
        !Number.isInteger(organizationId) ||
        organizationId <= 0
      ) {
        return res
          .status(400)
          .send("Valid organization is required.");
      }

      const organizationResult = await q(
        `
          SELECT
            id,
            name
          FROM organizations
          WHERE id = $1
          LIMIT 1
        `,
        [organizationId]
      );

      if (!organizationResult.rows.length) {
        return res
          .status(404)
          .send("Organization not found.");
      }

      const organization =
        organizationResult.rows[0];

      const usersResult = await q(
        `
          SELECT
            ou.id AS organization_user_id,
            ou.user_id,
            ou.role,
            ou.is_active,
            u.name,
            u.email,
            COALESCE(
              STRING_AGG(
                DISTINCT s.name,
                ', '
                ORDER BY s.name
              ) FILTER (
                WHERE s.id IS NOT NULL
              ),
              ''
            ) AS location_names
          FROM organization_users ou
          INNER JOIN users u
            ON u.id = ou.user_id
          LEFT JOIN location_users lu
            ON lu.user_id = ou.user_id
            AND lu.organization_id = ou.organization_id
            AND lu.is_active = true
          LEFT JOIN spaces s
            ON s.id = lu.space_id
            AND s.organization_id = ou.organization_id
          WHERE ou.organization_id = $1
          GROUP BY
            ou.id,
            ou.user_id,
            ou.role,
            ou.is_active,
            u.name,
            u.email
          ORDER BY
            ou.is_active DESC,
            u.name ASC,
            u.email ASC
        `,
        [organizationId]
      );

      const roleLabels = {
        owner: "Organization Administrator",
        organization_admin:
          "Organization Administrator",
        district_admin:
          "Organization Administrator",
        location_manager: "Location Manager",
        standard_user: "Standard User",
        read_only: "Read Only"
      };

      const userRows = usersResult.rows
        .map((user) => {
          const normalizedRole = String(
            user.role || "read_only"
          ).toLowerCase();

          const roleLabel =
            roleLabels[normalizedRole] ||
            "Read Only";

          const hasAllLocations =
            organizationRoleHasPermission(
              normalizedRole,
              "view_all_locations"
            );

          const locations = hasAllLocations
            ? "All Locations"
            : user.location_names ||
              "No Locations Assigned";

          const status = user.is_active
            ? "Active"
            : "Inactive";

          const statusBackground = user.is_active
            ? "#DCFCE7"
            : "#E5E7EB";

          const statusColor = user.is_active
            ? "#166534"
            : "#4B5563";

          return `
            <tr>
              <td>
                <strong>
                  ${escapeHtml(
                    user.name || "Unnamed User"
                  )}
                </strong>
                <div style="
                  margin-top:4px;
                  color:#64748B;
                  font-size:13px;
                ">
                  ${escapeHtml(user.email || "")}
                </div>
              </td>

              <td>
                ${escapeHtml(roleLabel)}
              </td>

              <td>
                ${escapeHtml(locations)}
              </td>

              <td>
                <span style="
                  display:inline-block;
                  padding:6px 10px;
                  border-radius:999px;
                  background:${statusBackground};
                  color:${statusColor};
                  font-size:12px;
                  font-weight:700;
                ">
                  ${status}
                </span>
              </td>

              
<td style="white-space:nowrap;">
  <a
    class="btn secondary"
    href="/org-user/${user.organization_user_id}/edit?organization_id=${organizationId}"
    style="
      padding:8px 12px;
      margin:0 6px 0 0;
    "
  >
    Edit
  </a>
<form
  method="POST"
  action="/org-user/${user.organization_user_id}/send-password-reset?organization_id=${organizationId}"
  style="
    display:inline;
    margin:0 6px 0 0;
  "
  onsubmit="
    return confirm(
      'Send a password reset link to this user?'
    );
  "
>
  <button
    type="submit"
    class="btn secondary"
    style="
      padding:8px 12px;
      margin:0;
    "
  >
    Reset Password
  </button>
</form>
  ${
    normalizedRole === "owner"
      ? ""
      : `
        <form
          method="POST"
          action="/org-user/${user.organization_user_id}/remove?organization_id=${organizationId}"
          style="
            display:inline;
            margin:0;
          "
          onsubmit="
            return confirm(
              'Remove this user from the organization? Their underlying Vivid account will not be deleted.'
            );
          "
        >
          <button
            type="submit"
            class="btn secondary"
            style="
              padding:8px 12px;
              margin:0;
            "
          >
            Deactivate
          </button>
        </form>
      `
  }
</td>
              
            </tr>
          `;
        })
        .join("");

      const emptyState = `
        <tr>
          <td
            colspan="5"
            style="
              text-align:center;
              padding:35px;
              color:#64748B;
            "
          >
            No organization users have been added.
          </td>
        </tr>
      `;

      res.send(
        orgPage(
          `${organization.name} Users`,
          `
            <div class="topbar">
              <div class="brand">
                Vivid Organizations
              </div>

              <h1>Users</h1>

              <p class="subtitle">
                Manage who can access
                ${escapeHtml(organization.name)}.
              </p>
            </div>

            <div class="wrap">

              <div style="
                display:flex;
                justify-content:space-between;
                align-items:center;
                gap:16px;
                flex-wrap:wrap;
                margin-bottom:18px;
              ">
                <a
                  class="btn secondary"
                  href="/org-organization/${organizationId}"
                >
                  Back to ${escapeHtml(
                    organization.name
                  )}
                </a>

                <a
                  class="btn"
                  href="/org-users/new"
                >
                  Add User
                </a>
              </div>

              <div class="card">
                <div style="overflow-x:auto;">
                  <table style="
                    width:100%;
                    border-collapse:collapse;
                  ">
                    <thead>
                      <tr style="
                        text-align:left;
                        border-bottom:1px solid #DCE5DC;
                      ">
                        <th style="padding:14px 12px;">
                          User
                        </th>

                        <th style="padding:14px 12px;">
                          Role
                        </th>

                        <th style="padding:14px 12px;">
                          Locations
                        </th>

                        <th style="padding:14px 12px;">
                          Status
                        </th>

                        <th style="padding:14px 12px;">
                          Action
                        </th>
                      </tr>
                    </thead>

                    <tbody>
                      ${
                        userRows ||
                        emptyState
                      }
                    </tbody>
                  </table>
                </div>
              </div>

            </div>
          `
        )
      );
    } catch (err) {
      console.error(
        "ORGANIZATION USERS ERROR:",
        err
      );

      res.status(500).send(
        "ORGANIZATION USERS ERROR: " +
          err.message
      );
    }
  }
);
