app.get(
  "/org-user/:organizationUserId/edit",
  requireOrganizationPermission("manage_users"),
  async (req, res) => {
    try {
    let organizationId = null;

if (
  req.session.user?.role === "super_admin"
) {
  organizationId = Number(
    req.query.organization_id
  );
}

if (
  !organizationId &&
  req.session.orgUser?.organization_id
) {
  organizationId = Number(
    req.session.orgUser.organization_id
  );
}

      const organizationUserId = Number(
        req.params.organizationUserId
      );

      if (
        !Number.isInteger(organizationId) ||
        organizationId <= 0 ||
        !Number.isInteger(organizationUserId) ||
        organizationUserId <= 0
      ) {
        return res
          .status(400)
          .send("Valid organization and user are required.");
      }

      /*
      =====================================================
      LOAD ORGANIZATION
      =====================================================
      */

      const organizationResult = await q(
        `
          SELECT
            id,
            name
          FROM organizations
          WHERE id = $1
            AND COALESCE(is_active, true) = true
          LIMIT 1
        `,
        [organizationId]
      );

      const organization =
        organizationResult.rows[0];

      if (!organization) {
        return res
          .status(404)
          .send("Organization not found.");
      }

      /*
      =====================================================
      LOAD ORGANIZATION USER
      =====================================================
      */

      const userResult = await q(
        `
          SELECT
            ou.id AS organization_user_id,
            ou.user_id,
            ou.role,
            ou.is_active,
            u.name,
            u.email
          FROM organization_users ou
          INNER JOIN users u
            ON u.id = ou.user_id
          WHERE ou.id = $1
            AND ou.organization_id = $2
          LIMIT 1
        `,
        [
          organizationUserId,
          organizationId
        ]
      );

      const user = userResult.rows[0];

      if (!user) {
        return res
          .status(404)
          .send("Organization user not found.");
      }

      const normalizedRole = String(
        user.role || "read_only"
      )
        .trim()
        .toLowerCase();

      const isOwner =
        normalizedRole === "owner";

      /*
      =====================================================
      LOAD LOCATIONS AND CURRENT ASSIGNMENTS
      =====================================================
      */

      const locationsResult = await q(
        `
          SELECT
            s.id,
            s.name,
            s.location,
            CASE
              WHEN lu.id IS NOT NULL THEN true
              ELSE false
            END AS is_assigned
          FROM spaces s
          LEFT JOIN location_users lu
            ON lu.space_id = s.id
            AND lu.organization_id = $1
            AND lu.user_id = $2
            AND COALESCE(lu.is_active, true) = true
          WHERE s.organization_id = $1
            AND COALESCE(s.is_archived, false) = false
          ORDER BY s.name ASC
        `,
        [
          organizationId,
          user.user_id
        ]
      );

      const locationOptions =
        locationsResult.rows
          .map((location) => {
            const locationDescription =
              location.location
                ? ` — ${escapeHtml(location.location)}`
                : "";

            return `
              <label style="
                display:flex;
                align-items:flex-start;
                gap:10px;
                padding:12px;
                margin:0;
                border:1px solid #DCE5DC;
                border-radius:10px;
                background:#FFFFFF;
                cursor:pointer;
              ">
                <input
                  type="checkbox"
                  name="location_ids"
                  value="${location.id}"
                  ${
                    location.is_assigned
                      ? "checked"
                      : ""
                  }
                  style="
                    width:auto;
                    margin-top:3px;
                  "
                />

                <span>
                  <strong>
                    ${escapeHtml(location.name)}
                  </strong>

                  <span style="
                    color:#64748B;
                    font-size:13px;
                  ">
                    ${locationDescription}
                  </span>
                </span>
              </label>
            `;
          })
          .join("");

      /*
      =====================================================
      ROLE OPTIONS
      =====================================================
      */

      const roleOption = (
        value,
        label
      ) => `
        <option
          value="${value}"
          ${
            normalizedRole === value
              ? "selected"
              : ""
          }
        >
          ${label}
        </option>
      `;

      const roleField = isOwner
        ? `
          <label>Role</label>

          <input
            type="text"
            value="Organization Owner"
            disabled
          />

          <input
            type="hidden"
            name="role"
            value="owner"
          />

          <p style="
            margin-top:-8px;
            color:#64748B;
            font-size:13px;
          ">
            The organization owner role cannot be changed.
          </p>
        `
        : `
          <label for="role">
            Role
          </label>

          <select
            id="role"
            name="role"
            required
            onchange="updateLocationVisibility()"
          >
            ${roleOption(
              "organization_admin",
              "Organization Administrator"
            )}

            ${roleOption(
              "location_manager",
              "Location Manager"
            )}

            ${roleOption(
              "standard_user",
              "Standard User"
            )}

            ${roleOption(
              "read_only",
              "Read Only"
            )}
          </select>
        `;

      /*
      =====================================================
      STATUS FIELD
      =====================================================
      */

      const statusField = isOwner
        ? `
          <label>Status</label>

          <input
            type="text"
            value="Active"
            disabled
          />

          <input
            type="hidden"
            name="is_active"
            value="true"
          />

          <p style="
            margin-top:-8px;
            color:#64748B;
            font-size:13px;
          ">
            The organization owner cannot be deactivated.
          </p>
        `
        : `
          <label for="is_active">
            Status
          </label>

          <select
            id="is_active"
            name="is_active"
            required
          >
            <option
              value="true"
              ${
                user.is_active
                  ? "selected"
                  : ""
              }
            >
              Active
            </option>

            <option
              value="false"
              ${
                !user.is_active
                  ? "selected"
                  : ""
              }
            >
              Inactive
            </option>
          </select>
        `;

      res.send(
        orgPage(
          `Edit ${user.name || "Organization User"}`,
          `
            <div class="topbar">
              <div class="brand">
                Vivid Organizations
              </div>

              <h1>Edit User</h1>

              <p class="subtitle">
                Update access for
                ${escapeHtml(
                  user.name || user.email
                )}.
              </p>
            </div>

            <div class="wrap">

              <div style="margin-bottom:20px;">
                <a
                  class="btn secondary"
                  href="/org-users"
                >
                  Back to Users
                </a>
              </div>

              <form
                method="POST"
                action="/org-user/${organizationUserId}/edit?organization_id=${organizationId}"
              >

                <div class="card">

                  <h2 style="margin-top:0;">
                    User Information
                  </h2>

                  <label for="name">
                    Full Name
                  </label>

                  <input
                    id="name"
                    name="name"
                    type="text"
                    maxlength="150"
                    value="${escapeHtml(user.name || "")}"
                    required
                  />

                  <label for="email">
                    Email Address
                  </label>

                  <input
                    id="email"
                    name="email"
                    type="email"
                    maxlength="255"
                    value="${escapeHtml(user.email || "")}"
                    required
                  />

                  ${roleField}

                  ${statusField}

                </div>

                <div
                  id="locationAssignmentCard"
                  class="card"
                  style="
                    margin-top:20px;
                    display:none;
                  "
                >
                  <h2 style="margin-top:0;">
                    Location Access
                  </h2>

                  <p style="
                    color:#64748B;
                    margin-bottom:18px;
                  ">
                    Select every location this user
                    should be able to access.
                  </p>

                  <div style="
                    display:grid;
                    grid-template-columns:
                      repeat(auto-fit, minmax(260px, 1fr));
                    gap:10px;
                  ">
                    ${
                      locationOptions ||
                      `
                        <p style="color:#64748B;">
                          No active locations are available.
                        </p>
                      `
                    }
                  </div>
                </div>

                <div style="
                  display:flex;
                  justify-content:flex-end;
                  gap:12px;
                  margin-top:20px;
                ">
                  <a
                    class="btn secondary"
                    href="/org-users"
                  >
                    Cancel
                  </a>

                  <button
                    class="btn"
                    type="submit"
                  >
                    Save Changes
                  </button>
                </div>

              </form>
            </div>

            <script>
              function updateLocationVisibility() {
                const roleElement =
                  document.getElementById("role");

                const locationCard =
                  document.getElementById(
                    "locationAssignmentCard"
                  );

                if (!roleElement || !locationCard) {
                  return;
                }

                const requiresLocations = [
                  "location_manager",
                  "standard_user",
                  "read_only"
                ].includes(roleElement.value);

                locationCard.style.display =
                  requiresLocations
                    ? "block"
                    : "none";

                if (!requiresLocations) {
                  document
                    .querySelectorAll(
                      'input[name="location_ids"]'
                    )
                    .forEach((checkbox) => {
                      checkbox.checked = false;
                    });
                }
              }

              updateLocationVisibility();
            </script>
          `
        )
      );
    } catch (err) {
      console.error(
        "EDIT ORGANIZATION USER FORM ERROR:",
        err
      );

      return res
        .status(500)
        .send(
          "EDIT ORGANIZATION USER FORM ERROR: " +
            err.message
        );
    }
  }
);

