const opportunitySummaryResult = await q(
  `
    SELECT
      COUNT(*)::integer
        AS total_opportunities,

      COUNT(*) FILTER (
        WHERE LOWER(
          COALESCE(status, 'available')
        ) = 'available'
      )::integer
        AS available_count,

      COUNT(*) FILTER (
        WHERE LOWER(
          COALESCE(status, '')
        ) = 'pending'
      )::integer
        AS pending_count,

      COUNT(*) FILTER (
        WHERE LOWER(
          COALESCE(status, '')
        ) = 'approved'
      )::integer
        AS approved_count,

      COUNT(*) FILTER (
        WHERE LOWER(
          COALESCE(status, '')
        ) = 'rejected'
      )::integer
        AS rejected_count,

      COUNT(*) FILTER (
        WHERE LOWER(
          COALESCE(status, '')
        ) = 'closed'
      )::integer
        AS closed_count,

      COALESCE(
        SUM(
          COALESCE(
            annual_price,
            price,
            0
          )
        ),
        0
      )
        AS total_inventory_value,

      COALESCE(
        SUM(
          COALESCE(
            annual_price,
            price,
            0
          )
        ) FILTER (
          WHERE LOWER(
            COALESCE(status, 'available')
          ) = 'available'
        ),
        0
      )
        AS available_revenue,

      COALESCE(
        SUM(
          COALESCE(
            annual_price,
            price,
            0
          )
        ) FILTER (
          WHERE LOWER(
            COALESCE(status, '')
          ) = 'pending'
        ),
        0
      )
        AS pending_revenue,

      COALESCE(
        SUM(
          COALESCE(
            annual_price,
            price,
            0
          )
        ) FILTER (
          WHERE LOWER(
            COALESCE(status, '')
          ) = 'approved'
        ),
        0
      )
        AS approved_revenue,

      COALESCE(
        SUM(
          COALESCE(
            annual_price,
            price,
            0
          )
        ) FILTER (
          WHERE LOWER(
            COALESCE(status, '')
          ) = 'rejected'
        ),
        0
      )
        AS rejected_revenue,

      COALESCE(
        SUM(
          COALESCE(
            annual_price,
            price,
            0
          )
        ) FILTER (
          WHERE LOWER(
            COALESCE(status, '')
          ) = 'closed'
        ),
        0
      )
        AS closed_revenue

    FROM organization_opportunities

   WHERE
  ${opportunitySummaryWhereParts.join(
    "\nAND "
  )}
  `,
  opportunitySummaryValues
);

