app.post(
  "/admin/advertiser-customer/:customerId/user/:userId/edit",
  requireSuperAdmin,
  async (req, res) => {
    try {

      const customerId =
        Number(req.params.customerId);

      const userId =
        Number(req.params.userId);

      const name =
        String(
          req.body.name || ""
        ).trim();

      const email =
        String(
          req.body.email || ""
        )
          .trim()
          .toLowerCase();

      if (!name || !email) {
        return res
          .status(400)
          .send(
            "Name and email are required."
          );
      }

      const result = await q(
        `
          UPDATE users

          SET
            name = $1,
            email = $2

          WHERE id = $3
            AND id = $4
            AND role = 'customer'

          RETURNING id
        `,
        [
          name,
          email,
          userId,
          customerId
        ]
      );

      if (!result.rows[0]) {
        return res
          .status(404)
          .send(
            "Advertiser user not found."
          );
      }

      return res.redirect(
        `/admin/advertiser-customer/${customerId}/users`
      );

    } catch (err) {

      if (err.code === "23505") {
        return res
          .status(400)
          .send(
            "Another Vivid user already uses this email address."
          );
      }

      console.error(
        "EDIT ADVERTISER USER ERROR:",
        err
      );

      return res
        .status(500)
        .send(
          "EDIT ADVERTISER USER ERROR: " +
          err.message
        );
    }
  }
);
