app.post(
  "/admin/users",
  requireSuperAdmin,
  async (req, res) => {
    try {

      const customerType =
        String(
          req.body.customer_type ||
          "advertiser"
        )
          .trim()
          .toLowerCase();


      const name =
        String(
          req.body.name || ""
        ).trim();

const companyName =
  String(
    req.body.company_name || ""
  ).trim();
      const email =
        String(
          req.body.email || ""
        )
          .trim()
          .toLowerCase();


      const password =
        String(
          req.body.password || ""
        );


      if (
        !email ||
        !password
      ) {
        return res
          .status(400)
          .send(
            "Email and password are required."
          );
      }
if (!companyName) {
  return res
    .status(400)
    .send(
      "Company / Organization Name is required."
    );
}

      /*
      =====================================================
      ADVERTISER CUSTOMER
      =====================================================
      */

      if (
        customerType === "advertiser"
      ) {

    await q(
  `
    INSERT INTO users (
      name,
      company_name,
      email,
      password,
      role
    )

    VALUES (
      $1,
      $2,
      $3,
      $4,
      'customer'
    )

    ON CONFLICT (email)

    DO UPDATE SET
      name = EXCLUDED.name,
      company_name = EXCLUDED.company_name,
      password = EXCLUDED.password,
      role = 'customer'
  `,
  [
    name || null,
    companyName,
    email,
    password
  ]
);

        return res.redirect(
          "/admin/users"
        );
      }


      /*
      =====================================================
      ENTERPRISE CUSTOMER
      =====================================================
      */

      if (
        customerType === "enterprise"
      ) {

       const organizationName =
  companyName;


        const organizationType =
          String(
            req.body.organization_type ||
            ""
          ).trim();


        const organizationRole =
          String(
            req.body.organization_role ||
            "organization_admin"
          )
            .trim()
            .toLowerCase();


        if (!organizationName) {

          return res
            .status(400)
            .send(
              "Organization name is required for an Enterprise customer."
            );
        }


        /*
        Create or update the login.
        */

        const userResult =
          await q(
            `
             INSERT INTO users (
  name,
  company_name,
  email,
  password,
  role
)

VALUES (
  $1,
  $2,
  $3,
  $4,
  'organization_user'
)

              ON CONFLICT (email)

            DO UPDATE SET
  name = EXCLUDED.name,
  company_name = EXCLUDED.company_name,
  password = EXCLUDED.password,
  role = 'organization_user'

              RETURNING id
            `,
         [
  name || null,
  companyName,
  email,
  password
]
          );


        const userId =
          Number(
            userResult.rows[0].id
          );


        /*
        Create the Enterprise organization.
        */

        const organizationResult =
          await q(
            `
              INSERT INTO organizations (
                customer_id,
                name,
                organization_type,
                contact_name,
                contact_email,
                is_active
              )

              VALUES (
                $1,
                $2,
                $3,
                $4,
                $5,
                true
              )

              RETURNING id
            `,
            [
              userId,
              organizationName,
              organizationType || "",
              name || "",
              email
            ]
          );


        const organizationId =
          Number(
            organizationResult.rows[0].id
          );


        /*
        Connect the login to the Enterprise
        organization and assign its role.
        */

        await q(
          `
            INSERT INTO organization_users (
              organization_id,
              user_id,
              role,
              is_active
            )

            VALUES (
              $1,
              $2,
              $3,
              true
            )

            ON CONFLICT
              (organization_id, user_id)

            DO UPDATE SET
              role = EXCLUDED.role,
              is_active = true
          `,
          [
            organizationId,
            userId,
            organizationRole
          ]
        );


        return res.redirect(
          `/org-organization/${organizationId}?organization_id=${organizationId}`
        );
      }


      return res
        .status(400)
        .send(
          "Invalid customer type."
        );


    } catch (err) {

      console.error(
        "CREATE CUSTOMER ERROR:",
        err
      );

      return res
        .status(500)
        .send(
          "CREATE CUSTOMER ERROR: " +
          err.message
        );
    }
  }
);
    
