app.post("/admin/campaigns/:id/archive", requireAdmin, async (req, res) => {
  try {
    const { id } = req.params;
    const reason = req.body.reason || "Archived by admin";

    await q(`
      UPDATE campaigns
      SET
        archived = true,
        archived_at = NOW(),
        archive_reason = $1
      WHERE id = $2
    `, [reason, id]);

    res.redirect("/admin");

  } catch (err) {
    console.error("ARCHIVE CAMPAIGN ERROR:", err);
    res.status(500).send(err.message);
  }
});
app.post("/admin/archive-schedule/:id", requireAdmin, async (req, res) => {
  try {
    await q(
      `UPDATE campaign_schedules
       SET is_active = false
       WHERE id=$1`,
      [Number(req.params.id)]
    );

    res.redirect("/admin/schedule");
  } catch (e) {
    res.status(500).send("Archive failed: " + e.message);
  }
});
async function buildExportReportRows(
  req,
  startDate,
  endDate,
  locationId,
  qrId,
  campaignId,
  status
) {
  const currentUser = req.session.user;

  const isSuperAdmin =
    currentUser.role === "super_admin";

  const userId =
    isSuperAdmin
      ? null
      : currentUser.id;

  const campaignsResult = await q(
    `
      SELECT
        c.id AS campaign_id,
        c.name AS campaign_name,
        c.advertiser,
        c.avg_customer_value,

        COALESCE(
          c.is_archived,
          false
        ) AS is_archived,

        STRING_AGG(
          DISTINCT qr.name,
          ', '
        ) AS qr_names,

        STRING_AGG(
          DISTINCT s.name,
          ', '
        ) AS location_names

      FROM campaigns c

      LEFT JOIN qr_campaigns qc
        ON qc.campaign_id = c.id
       AND COALESCE(
             qc.is_active,
             true
           ) = true

      LEFT JOIN qr_codes qr
        ON qr.id = qc.qr_id

      LEFT JOIN spaces s
        ON s.id = qr.space_id

      WHERE (
        $1::int IS NULL
        OR c.user_id = $1
        OR s.user_id = $1
      )

        AND (
          $2::text = ''
          OR c.id::text = $2::text
        )

        AND (
          $3::text = ''
          OR qr.id::text = $3::text
        )

        AND (
          $4::text = ''
          OR s.id::text = $4::text
        )

        AND (
          $5::text = 'all'

          OR (
            $5::text = 'active'
            AND COALESCE(
                  c.is_archived,
                  false
                ) = false
          )

          OR (
            $5::text = 'archived'
            AND COALESCE(
                  c.is_archived,
                  false
                ) = true
          )
        )

      GROUP BY
        c.id,
        c.name,
        c.advertiser,
        c.avg_customer_value,
        c.is_archived

      ORDER BY
        c.name ASC
    `,
    [
      userId,
      campaignId || "",
      qrId || "",
      locationId || "",
      status || "all"
    ]
  );

  const reportRows = [];

  for (
    const campaignRow of
    campaignsResult.rows
  ) {
    /*
    =========================================================
    CENTRALIZED CAMPAIGN PERFORMANCE

    Uses the same analytics engine as Campaign, QR,
    and Location pages.
    =========================================================
    */

    const performance =
      await getPerformanceMetrics({
        campaignId:
          Number(
            campaignRow.campaign_id
          ),

        qrId:
          qrId
            ? Number(qrId)
            : null,

        locationId:
          locationId
            ? Number(locationId)
            : null,

        startDate,
        endDate
      });

    /*
    =========================================================
    LEGACY / TECHNICAL ACTIVITY METRICS

    Preserved for technical and operational reporting.
    =========================================================
    */

    const technicalResult = await q(
      `
        SELECT
          COUNT(*) FILTER (
            WHERE e.type = 'scan'
          )::int AS scans,

          COUNT(*) FILTER (
            WHERE e.type = 'offer'
          )::int AS offer_clicks,

          COUNT(*) FILTER (
            WHERE e.type = 'maps'
          )::int AS map_clicks,

          COUNT(*) FILTER (
            WHERE e.type = 'waze'
          )::int AS waze_clicks

        FROM events e

        LEFT JOIN qr_codes qr
          ON qr.id = e.qr_id

        WHERE e.campaign_id = $1

          AND e.created_at::date
              BETWEEN $2::date
                  AND $3::date

          AND (
            $4::text = ''
            OR qr.space_id::text =
               $4::text
          )

          AND (
            $5::text = ''
            OR e.qr_id::text =
               $5::text
          )
      `,
      [
        campaignRow.campaign_id,
        startDate,
        endDate,
        locationId || "",
        qrId || ""
      ]
    );

    const technical =
      technicalResult.rows[0] || {};

    const scans =
      Number(technical.scans || 0);

    const offerClicks =
      Number(
        technical.offer_clicks || 0
      );

    const mapClicks =
      Number(
        technical.map_clicks || 0
      );

    const wazeClicks =
      Number(
        technical.waze_clicks || 0
      );

    const intent =
      offerClicks +
      mapClicks +
      wazeClicks;

    /*
    =========================================================
    CUSTOMER ACTION / URL PERFORMANCE

    Every campaign destination is retained, including URLs
    that have no activity during the selected period.
    =========================================================
    */

    const customerActionsResult =
      await q(
        `
          SELECT
            cd.id,
            cd.name,
            cd.destination_type,
            cd.destination_url,
            cd.conversion_url,
            cd.estimated_value,
            cd.display_order,
            cd.is_active,

            COUNT(e.id) FILTER (
              WHERE e.type =
                    'destination_click'
            )::int AS clicks,

            COUNT(
              DISTINCT e.vivid_click_id
            ) FILTER (
              WHERE e.type =
                    'destination_click'

                AND e.vivid_click_id
                    IS NOT NULL

                AND TRIM(
                      e.vivid_click_id
                    ) <> ''
            )::int AS visitors,

            COUNT(e.id) FILTER (
              WHERE e.type =
                    'conversion'
            )::int AS conversions,

            COALESCE(
              SUM(e.value) FILTER (
                WHERE e.type =
                      'conversion'
              ),
              0
            )::numeric AS revenue_generated,

            MAX(e.created_at) FILTER (
              WHERE e.type =
                    'destination_click'
            ) AS last_activity

          FROM campaign_destinations cd

          LEFT JOIN events e
            ON e.campaign_destination_id =
               cd.id

           AND e.campaign_id =
               cd.campaign_id

           AND e.created_at::date
               BETWEEN $2::date
                   AND $3::date

           AND (
             $4::text = ''

             OR e.qr_id IN (
               SELECT id
               FROM qr_codes
               WHERE space_id::text =
                     $4::text
             )
           )

           AND (
             $5::text = ''
             OR e.qr_id::text =
                  $5::text
           )

          WHERE cd.campaign_id = $1

          GROUP BY
            cd.id,
            cd.name,
            cd.destination_type,
            cd.destination_url,
            cd.conversion_url,
            cd.estimated_value,
            cd.display_order,
            cd.is_active

          ORDER BY
            cd.display_order ASC,
            cd.id ASC
        `,
        [
          campaignRow.campaign_id,
          startDate,
          endDate,
          locationId || "",
          qrId || ""
        ]
      );

    const customerActions =
      customerActionsResult.rows.map(
        action => {
          const visitors =
            Number(action.visitors || 0);

          const clicks =
            Number(action.clicks || 0);

          const conversions =
            Number(
              action.conversions || 0
            );

          const revenueGenerated =
            Number(
              action.revenue_generated ||
              0
            );

          return {
            id:
              Number(action.id),

            name:
              action.name || "",

            type:
              action.destination_type ||
              "website",

            destinationUrl:
              action.destination_url ||
              "",

            conversionUrl:
              action.conversion_url ||
              "",

            conversionValue:
              Number(
                action.estimated_value ||
                0
              ),

            displayOrder:
              Number(
                action.display_order ||
                0
              ),

            status:
              action.is_active
                ? "Active"
                : "Inactive",

            visitors,
            clicks,
            conversions,

            conversionRate:
              visitors > 0
                ? conversions /
                  visitors *
                  100
                : 0,

            revenueGenerated,

            revenuePerVisitor:
              visitors > 0
                ? revenueGenerated /
                  visitors
                : 0,

            revenuePerClick:
              clicks > 0
                ? revenueGenerated /
                  clicks
                : 0,

            revenuePerConversion:
              conversions > 0
                ? revenueGenerated /
                  conversions
                : 0,

            lastActivity:
              action.last_activity ||
              null
          };
        }
      );

    const allocatedCost =
      await allocatedSpotCostForCampaign(
        campaignRow.campaign_id,
        startDate,
        endDate
      );

    const cac =
      performance.conversions > 0
        ? allocatedCost /
          performance.conversions
        : 0;

    const roi =
      allocatedCost > 0
        ? (
            (
              performance
                .revenueGenerated -
              allocatedCost
            ) /
            allocatedCost
          ) * 100
        : 0;

    reportRows.push({
      campaignId:
        Number(
          campaignRow.campaign_id
        ),

      campaignName:
        campaignRow.campaign_name ||
        "",

      advertiser:
        campaignRow.advertiser ||
        "",

      qrNames:
        campaignRow.qr_names ||
        "",

      locationNames:
        campaignRow.location_names ||
        "",

      status:
        campaignRow.is_archived
          ? "Archived"
          : "Active",

      scans,
      offerClicks,
      mapClicks,
      wazeClicks,
      intent,

      visitors:
        performance.visitors,

      clicks:
        performance.clicks,

      conversions:
        performance.conversions,

      visitorsConverted:
        performance
          .visitorsConverted,

      visitorConversionRate:
        performance
          .visitorConversionRate,

      revenue:
        performance
          .revenueGenerated,

      revenueGenerated:
        performance
          .revenueGenerated,

      revenuePerVisitor:
        performance
          .revenuePerVisitor,

      revenuePerClick:
        performance
          .revenuePerClick,

      revenuePerConversion:
        performance
          .revenuePerConversion,

      allocatedCost,
      cac,
      roi,

      customerActions
    });
  }

  return reportRows;
}


app.get("/admin/reports", requireLogin, async (req, res) => {
  try {
    const today = new Date().toISOString().slice(0, 10);

    const startDate = req.query.start_date || today;
    const endDate = req.query.end_date || today;
    const locationId = req.query.location_id || "";
    const qrId = req.query.qr_id || "";
    const campaignId = req.query.campaign_id || "";
    const status = (req.query.status || "all").toLowerCase();

    const currentUser = req.session.user;
    const isSuperAdmin = currentUser.role === "super_admin";
    const userId = isSuperAdmin ? null : currentUser.id;

    const locations = await q(`
      SELECT DISTINCT s.id, s.name
      FROM spaces s
      WHERE ($1::int IS NULL OR s.user_id = $1)
      ORDER BY s.name
    `, [userId]);

    const qrs = await q(`
      SELECT DISTINCT qr.id, qr.name
      FROM qr_codes qr
      LEFT JOIN spaces s ON s.id = qr.space_id
      WHERE ($1::int IS NULL OR s.user_id = $1)
      ORDER BY qr.name
    `, [userId]);

    const campaigns = await q(`
      SELECT DISTINCT c.id, c.name
      FROM campaigns c
      LEFT JOIN qr_campaigns qc ON qc.campaign_id = c.id
      LEFT JOIN qr_codes qr ON qr.id = qc.qr_id
      LEFT JOIN spaces s ON s.id = qr.space_id
      WHERE ($1::int IS NULL OR c.user_id = $1 OR s.user_id = $1)
      ORDER BY c.name
    `, [userId]);

    const reportRows = await buildExportReportRows(
      req,
      startDate,
      endDate,
      locationId,
      qrId,
      campaignId,
      status
    );

    const summary = reportRows.reduce((t, r) => {
      t.scans += r.scans;
      t.offerClicks += r.offerClicks;
      t.mapClicks += r.mapClicks;
      t.wazeClicks += r.wazeClicks;
      t.intent += r.intent;
      t.conversions += r.conversions;
      t.revenue += r.revenue;
      t.allocatedCost += r.allocatedCost;
      return t;
    }, {
      scans: 0,
      offerClicks: 0,
      mapClicks: 0,
      wazeClicks: 0,
      intent: 0,
      conversions: 0,
      revenue: 0,
      allocatedCost: 0
    });

    summary.cac = summary.conversions > 0 ? summary.allocatedCost / summary.conversions : 0;
    summary.roi = summary.allocatedCost > 0 ? ((summary.revenue - summary.allocatedCost) / summary.allocatedCost) * 100 : 0;

    res.send(page("Reports", `
      <h1>Export Center</h1>

      <form method="GET" action="/admin/reports" style="display:flex;gap:12px;align-items:end;flex-wrap:wrap;margin-bottom:20px;">
        <div>
          <label>Start Date</label><br>
          <input type="date" name="start_date" value="${startDate}">
        </div>

        <div>
          <label>End Date</label><br>
          <input type="date" name="end_date" value="${endDate}">
        </div>

        <div>
          <label>Location</label><br>
          <select name="location_id">
            <option value="">All Locations</option>
            ${locations.rows.map(l => `
              <option value="${l.id}" ${String(l.id) === String(locationId) ? "selected" : ""}>
                ${l.name}
              </option>
            `).join("")}
          </select>
        </div>

        <div>
          <label>QR Code</label><br>
          <select name="qr_id">
            <option value="">All QR Codes</option>
            ${qrs.rows.map(qr => `
              <option value="${qr.id}" ${String(qr.id) === String(qrId) ? "selected" : ""}>
                ${qr.name}
              </option>
            `).join("")}
          </select>
        </div>

        <div>
          <label>Campaign</label><br>
          <select name="campaign_id">
            <option value="">All Campaigns</option>
            ${campaigns.rows.map(c => `
              <option value="${c.id}" ${String(c.id) === String(campaignId) ? "selected" : ""}>
                ${c.name}
              </option>
            `).join("")}
          </select>
        </div>

        <div>
          <label>Status</label><br>
          <select name="status">
            <option value="all" ${status === "all" ? "selected" : ""}>All</option>
            <option value="active" ${status === "active" ? "selected" : ""}>Active</option>
            <option value="archived" ${status === "archived" ? "selected" : ""}>Archived</option>
          </select>
        </div>

<button type="submit">
  Run Report
</button>

<button
  type="submit"
  formaction="/export/events.csv"
  formmethod="get"
>
  Export Raw Events CSV
</button>

<button
  type="submit"
  formaction="/export/report.xlsx"
  formmethod="get"
>
  Export Executive Excel
</button>

<button
  type="submit"
  formaction="/export/report.pdf"
  formmethod="get"
>
  Export Executive PDF
</button>


      </form>

      <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:24px 0;">
        <div class="card"><h3>Scans</h3><p>${summary.scans}</p></div>
        <div class="card"><h3>Total Intent</h3><p>${summary.intent}</p></div>
        <div class="card"><h3>Conversions</h3><p>${summary.conversions}</p></div>
        <div class="card"><h3>Revenue</h3><p>${money(summary.revenue)}</p></div>
        <div class="card"><h3>Allocated Cost</h3><p>${money(summary.allocatedCost)}</p></div>
        <div class="card"><h3>CAC</h3><p>${money(summary.cac)}</p></div>
        <div class="card"><h3>ROI</h3><p>${pct(summary.roi)}</p></div>
      </div>

      <h2>Detailed Results</h2>

      <table>
        <tr>
          <th>Advertiser</th>
          <th>Campaign</th>
          <th>QR Codes</th>
          <th>Locations</th>
          <th>Status</th>
          <th>Scans</th>
          <th>Offers</th>
          <th>Maps</th>
          <th>Waze</th>
          <th>Intent</th>
          <th>Conversions</th>
          <th>Revenue</th>
          <th>Allocated Cost</th>
          <th>CAC</th>
          <th>ROI</th>
        </tr>

        ${reportRows.map(r => `
          <tr>
            <td>${r.advertiser}</td>
            <td>${r.campaignName}</td>
            <td>${r.qrNames}</td>
            <td>${r.locationNames}</td>
            <td>${r.status}</td>
            <td>${r.scans}</td>
            <td>${r.offerClicks}</td>
            <td>${r.mapClicks}</td>
            <td>${r.wazeClicks}</td>
            <td>${r.intent}</td>
            <td>${r.conversions}</td>
            <td>${money(r.revenue)}</td>
            <td>${money(r.allocatedCost)}</td>
            <td>${money(r.cac)}</td>
            <td class="${r.roi >= 0 ? "good" : "bad"}">${pct(r.roi)}</td>
          </tr>
        `).join("")}
      </table>
    `));
  } catch (e) {
    console.error("REPORTS FULL ERROR:", e);
    res.status(500).send("REPORTS ERROR: " + e.message);
  }
});

/*
=========================================================
ONE-TIME OPPORTUNITY STATUS REPAIR
Remove after successfully running once.
=========================================================
*/

app.get(
  "/admin/repair-opportunity-statuses",
  requireLogin,
  requireSuperAdmin,
  async (req, res) => {
    try {
      const repairResult = await q(`
        WITH latest_requests AS (
          SELECT DISTINCT ON (
            organization_id,
            opportunity_id
          )
            organization_id,
            opportunity_id,
            status AS request_status
          FROM organization_advertising_requests
          WHERE opportunity_id IS NOT NULL
          ORDER BY
            organization_id,
            opportunity_id,
            submitted_at DESC,
            id DESC
        )

        UPDATE organization_opportunities oo

        SET
          status = CASE
            WHEN LOWER(
              COALESCE(lr.request_status, '')
            ) = 'pending'
              THEN 'Pending'

            WHEN LOWER(
              COALESCE(lr.request_status, '')
            ) = 'approved'
              THEN 'Approved'

            WHEN LOWER(
              COALESCE(lr.request_status, '')
            ) = 'rejected'
              THEN 'Rejected'

            WHEN LOWER(
              COALESCE(lr.request_status, '')
            ) = 'closed'
              THEN 'Closed'

            ELSE oo.status
          END,

          updated_at = CURRENT_TIMESTAMP

        FROM latest_requests lr

        WHERE oo.organization_id =
              lr.organization_id

          AND oo.id =
              lr.opportunity_id

        RETURNING
          oo.id,
          oo.organization_id,
          oo.title,
          oo.status,
          COALESCE(
            oo.annual_price,
            oo.price,
            0
          ) AS value
      `);

      return res.json({
        success: true,
        updated_count:
          repairResult.rows.length,
        updated_opportunities:
          repairResult.rows
      });

    } catch (err) {
      console.error(
        "OPPORTUNITY STATUS REPAIR ERROR:",
        err
      );

      return res.status(500).json({
        success: false,
        error: err.message
      });
    }
  }
);
